INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('c572551d-bfce-4102-a276-6d7b02d6bb75', 'Contoso', 0, '{"industry":"Software / SaaS","business":"Contoso makes rostering and payroll software for 1,800 New Zealand hospitality and retail businesses.","website_url":null}', 'Software Engineer (TypeScript)', '- 2+ years building web applications professionally
- Strong TypeScript and React
- Experience with Node.js and relational databases
- A habit of writing tests
- Nice to have: AWS, GitHub Actions, Playwright.', 'Permanent', 'Auckland Central', 'Contoso/Contoso_Software-Engineer-TypeScript.pdf', 'Reject', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980980 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3418580 seconds'), 'Join Contoso''s Scheduling squad to build rostering and payroll features for hospitality and retail customers, including shift planning, leave approvals and labour-cost forecasts. You will work end to end across a Next.js front end and Node.js services, design REST APIs backed by PostgreSQL, write automated tests, maintain the CI pipeline, and pair with product and design. Hybrid working from the Karangahape Road office.', 'SEEK', NULL, '["TypeScript","React","Node.js","Next.js","PostgreSQL","REST APIs","AWS","GitHub Actions","Playwright"]', 'Not progressing', 'e2c76395-8cbf-4805-b1a5-39a01e136aca', 0, 'Tech interview', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4887380 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4282580 seconds'), NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('8a0fbcf7-a2f4-4b1b-9dbd-b9de1529c903', 'Fabrikam', 0, '{"industry":"Document-processing software","business":"Fabrikam builds document-processing software for New Zealand councils and utilities.","website_url":null}', 'AI Engineer', '- 3+ years of software engineering experience
- Production experience with LLM APIs and structured outputs
- Strong Python; TypeScript is a plus
- Experience with evaluation and monitoring of ML or LLM systems
- SQL and PostgreSQL
- Nice to have: retrieval-augmented generation, pgvector, AWS Lambda.', 'Permanent', 'Wellington (hybrid)', 'Fabrikam/Fabrikam_AI-Engineer.pdf', 'Offer', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462580 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1863380 seconds'), 'Fabrikam is hiring an AI Engineer in Wellington (hybrid) on a permanent full-time basis. The role builds LLM-powered extraction pipelines that convert unstructured documents into validated structured data. It involves prompt design, tool calls, JSON schemas, evaluation sets, tracing, and production services in Python and TypeScript on AWS.', 'Other', NULL, '["Python","TypeScript","AWS","SQL","PostgreSQL","pgvector","AWS Lambda"]', 'Offer received', 'ac7338a8-0d11-4b00-b48f-9f910f253adc', 0, 'Offer', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4368980 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3850580 seconds'), NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('7021c416-2f2e-4d84-ac36-2289ddd4de1e', 'Tailwind Traders', 0, '{"industry":"Hardware retail","business":"Tailwind Traders is an online hardware retailer shipping to every corner of Aotearoa from its Penrose warehouse.","website_url":null}', 'Full Stack Developer', '- 3+ years of full-stack JavaScript or TypeScript
- Next.js or similar React framework in production
- PostgreSQL or MySQL
- Experience integrating third-party APIs
- Bonus points for Shopify, Stripe or GraphQL experience', 'Permanent', 'Auckland (hybrid)', 'Tailwind-Traders/Tailwind-Traders_Full-Stack-Developer.pdf', 'Reject', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857780 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2554580 seconds'), 'Tailwind Traders is an online hardware retailer with a 12-person in-house team. The Full Stack Developer builds storefront and checkout features in Next.js and React, maintains order and inventory APIs in Node.js, integrates courier and payment providers, and improves site performance and accessibility. Permanent role based in Auckland with hybrid work.', 'LinkedIn', NULL, '["Next.js","React","Node.js","JavaScript","TypeScript","PostgreSQL","MySQL","Shopify","Stripe","GraphQL"]', 'Not progressing', 'eea14fb5-829e-490c-89b5-7dc981b25c77', 0, 'Applied', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3764180 seconds'), NULL, NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('10c6be8e-5c3c-40ff-8ffe-7298e478f169', 'Woodgrove Bank', 0, '{"industry":"Banking","business":"Woodgrove Bank is a New Zealand-owned bank serving 300,000 customers.","website_url":null}', 'Software Engineer, Platform', '- 3+ years in software engineering, ideally on platform or backend services
- C# and .NET (or Java and willingness to learn .NET)
- Azure or another major cloud
- Infrastructure as code (Terraform or Bicep)
- Comfortable on an on-call roster', 'Permanent', 'Auckland CBD (hybrid)', 'Woodgrove-Bank/Woodgrove-Bank_Software-Engineer-Platform.pdf', 'Reject', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252980 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2381780 seconds'), 'Woodgrove Bank''s Platform team builds shared services such as identity, payments, notifications and observability. The engineer builds and runs internal platform services in C# and .NET on Azure, improves deployment pipelines and developer tooling, owns reliability through monitoring, alerting and incident reviews, and works with security on safe-by-default patterns. The role includes an on-call roster.', 'Other', NULL, '["C#",".NET","Azure","Java","Terraform","Bicep"]', 'Not progressing', 'c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 0, 'HR screen', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3159380 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2640980 seconds'), NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('2b7e8f05-1e37-4b4d-85d4-91083d7f9838', 'Litware', 0, '{"industry":"Agritech","business":"Litware builds pasture-growth forecasting for dairy farms using satellite imagery and on-farm sensors.","website_url":null}', 'Machine Learning Engineer', '- 3+ years building ML systems in production
- Strong Python and PyTorch
- Experience with time-series or geospatial data
- AWS (S3, SageMaker or Lambda)
- A postgraduate degree in a quantitative field is an advantage', 'Permanent', 'Remote within New Zealand', 'Litware/Litware_Machine-Learning-Engineer.pdf', 'Applied', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561780 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2468180 seconds'), 'Litware is hiring a Machine Learning Engineer to train, evaluate and ship forecasting models in Python. The role builds data pipelines with PyTorch, pandas and SQL on AWS, puts models into production and monitors drift, and works with agronomists to turn forecasts into decisions farmers trust. Fully remote within New Zealand, with a quarterly team week in Hamilton. Salary is $130k to $150k.', 'Other', NULL, '["Python","PyTorch","pandas","SQL","AWS","S3","SageMaker","Lambda"]', 'Applied online', '91b7d489-0381-41d0-bd4c-546ebdddb519', 0, 'Applied', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2468180 seconds'), NULL, NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('1827585d-7037-47fb-8e21-5a6eb0eb05ed', 'Fourth Coffee', 0, '{"industry":"Coffee","business":"Fourth Coffee roasts and delivers coffee subscriptions to 40,000 homes and offices across New Zealand.","website_url":null}', 'Frontend Engineer', '- 2+ years of professional frontend development
- Strong React and TypeScript
- Care for accessibility (WCAG) and performance
- Experience with component testing (Vitest, Testing Library or Playwright)
- Nice to have: Next.js, design tokens, analytics.', 'Permanent', 'Christchurch (hybrid, Sydenham)', 'Fourth-Coffee/Fourth-Coffee_Frontend-Engineer.pdf', 'Tech interview', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043380 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-999380 seconds'), 'Fourth Coffee is hiring a Frontend Engineer for its product team. The role builds the customer subscription app in React and TypeScript, owns the design system and component library, and improves speed and accessibility across devices. It works with design and two backend engineers. Hybrid from the Sydenham roastery in Christchurch.', 'Company Website', NULL, '["React","TypeScript","Vitest","Testing Library","Playwright","Next.js"]', 'Technical interview', 'cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 0, 'Tech interview', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1949780 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1517780 seconds'), NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('24ac23ae-27d9-4f0f-bc0e-bfd2f743ccbc', 'Wide World Importers', 0, '{"industry":null,"business":"Wide World Importers distributes homeware from 60 suppliers to retailers across New Zealand, connecting its warehouse, ERP and customers'' ordering systems.","website_url":null}', 'Integration Developer', '- 3+ years of backend or integration development
- Node.js and TypeScript
- AWS serverless services
- Experience parsing messy partner data: CSV, EDI, XML or email
- SQL', 'Permanent', 'Auckland (Mount Wellington)', 'Wide-World-Importers/Wide-World-Importers_Integration-Developer.pdf', 'HR screen', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438580 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-826580 seconds'), 'Build and maintain integrations in Node.js and TypeScript for Wide World Importers, a homeware distributor. Design REST and event-driven interfaces with suppliers and retailers, run serverless workloads on AWS Lambda, SQS and S3, monitor integrations, fix failures quickly and document every interface. Salary $110k to $125k plus a performance bonus.', 'Trade Me Jobs', NULL, '["Node.js","TypeScript","REST","event-driven","AWS Lambda","AWS SQS","AWS S3","SQL","CSV","EDI","XML"]', 'Recruiter call', 'a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 0, 'HR screen', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1344980 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-826580 seconds'), NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('a3a71837-e5cb-4854-b98c-41bc8dbe3d79', 'Trey Research', 0, '{"industry":"Public policy research","business":"Runs public-policy surveys and research for New Zealand government agencies.","website_url":null}', 'Data and AI Engineer', '- 2+ years in data engineering or software engineering
- Strong Python and SQL
- Experience with LLM APIs or NLP
- Clear communication with non-technical researchers', 'Fixed-term', 'Wellington', 'Trey-Research/Trey-Research_Data-and-AI-Engineer.pdf', 'Applied', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-747380 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-653780 seconds'), 'Build data pipelines and LLM components for a research assistant that summarises thousands of open-text survey answers and links findings back to supporting answers. Work with researchers on evaluation sets and accuracy, handle sensitive data carefully, and document every pipeline. Fixed-term role in Wellington.', 'Other', NULL, '["Python","SQL","dbt","LLM APIs","NLP"]', 'Applied online', 'bba3fc66-3c9b-4b61-8301-f495a05a4a8b', 0, 'Applied', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-653780 seconds'), NULL, NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('45058857-e467-4d11-9fb4-eb682880b3e6', 'Proseware Talent', 1, NULL, 'AI Developer (LLM Applications)', '- 3+ years of software development, with recent hands-on LLM work
- TypeScript and Node.js
- Experience with retrieval (RAG) and vector databases
- Comfortable working directly with customers', 'Permanent', 'Auckland (hybrid, 3 days in the office)', 'Proseware-Talent/Proseware-Talent_AI-Developer-LLM-Applications.pdf', 'Saved', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401780 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401180 seconds'), 'An AI Developer role with an Auckland SaaS company in property management, recruited by Proseware Talent. The developer joins the product team to add AI features across the platform, including automated maintenance-request triage, lease document Q&A and a natural-language reporting assistant. Work includes building LLM features, tool-calling agents, retrieval over customer documents, and monitoring model quality in production. Hybrid, three days in the office.', 'Other', NULL, '["TypeScript","Node.js","LLM","RAG","vector databases"]', '', 'a792e88d-66f1-4b18-9b51-0aad41d99551', 0, 'Saved', NULL, NULL, NULL, NULL, NULL);
INSERT INTO Job (uuid, sCompany, bAgency, sCompanyMeta, sJobTitle, sJobRequirement, sContractType, sLocation, sCoverLetterPath, sStatus, bDelete, dtDateTime, dtUpdateDateTime, sJobSummary, sSource, sSourceUrl, sTechStack, sNote, sRunID, bError, sDeepestStatus, dtApplied, dtFirstResponse, sMatch, iMatchScore, sMatchMeta) VALUES ('80a2214a-6f45-4df8-81a2-e8fb81e02c5c', 'Alpine Ski House', 0, '{"industry":null,"business":"Alpine Ski House runs lift-pass, lesson and rental bookings for four ski areas in the Southern Alps.","website_url":null}', 'Backend Engineer', '- 3+ years of backend development
- TypeScript and Node.js
- PostgreSQL and caching
- Experience with serverless or edge platforms
- Calm under pressure', 'Permanent', 'Queenstown or remote (NZ)', 'Alpine-Ski-House/Alpine-Ski-House_Backend-Engineer.pdf', 'Saved', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-142580 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-141980 seconds'), 'Backend Engineer at Alpine Ski House building booking and payment services in TypeScript on Node.js. Scale APIs for 50x winter traffic, run services on Cloudflare Workers and AWS, and improve observability. Requires 3+ years backend development plus TypeScript, Node.js, PostgreSQL, caching, and serverless or edge platform experience. Queenstown or remote in New Zealand.', 'Other', NULL, '["TypeScript","Node.js","Cloudflare Workers","AWS","PostgreSQL"]', '', 'e318a497-9f06-4d81-919b-481f0902b565', 0, 'Saved', NULL, NULL, NULL, NULL, NULL);

