INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561780 seconds'), 1235, 463, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an open Machine Learning Engineer role with responsibilities, requirements, location, and salary.","sLooksLike":null,"model":"deepseek-flash","apiMs":1235,"finishReason":"stop","reasoning":"We need answer JSON only. Need decide job ad. Clearly job advertisement. Return bIsJobPost true, reason, sLooksLike null. Ensure schema.","reasoningChars":136,"inputChars":743,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\":true,\"sReason\":\"It describes an open Machine Learning Engineer role with responsibilities, requirements, location, and salary.\",\"sLooksLike\":null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561779 seconds'), 9709, 3068, 1, '[]', '{"model":"deepseek-flash","apiMs":9708,"finishReason":"stop","reasoning":"We need answer JSON only. Need parse. Need be careful.\n\nLet''s inspect advert.\n\nTitle: Machine Learning Engineer\nCompany: Litware\nLocation: Remote within New Zealand\nFull time. Contract type? \"Full time\" likely Permanent? Since no employment type? They say Full time. Schema says sContractType options include Permanent | Fixed-term | Part-time | Contract | Casual | Internship - use Permanent when advert does not say. \"Full time\" is not in enum? It says use Permanent when advert does not say. Full time indicates employment type but not contract type. Could be Permanent? Hmm. They explicitly say \"Full time\" but not whether permanent/fixed-term. sContractType allowed options don''t include Full-time. Instruction says when advert does not state employment type, use \"Permanent\". It does state \"Full time\", but not contract type. Could we choose Permanent? The allowed values include Part-time etc. Full time maps maybe Permanent? But \"Fixed-term\" could be full time. Safer? The instruction: sContractType: when the advert does not state employment type, use \"Permanent\". It is never null. \"Full time\" states employment type (full-time). But no allowed \"Full-time\". Hmm. The schema provided: \"Permanent | Fixed-term | Part-time | Contract | Casual | Internship - use Permanent when the advert does not say\". Here it says \"Full time\", not one of those. In such cases perhaps treat as Permanent? Or maybe Part-time? No. Full time is typically permanent unless specified. But instruction says use Permanent when advert does not state. It does state full time, but not \"Permanent\". I''d choose Permanent because full-time roles default to permanent if not stated, and allowed options. Need maybe not infer? But the rule says when does not state employment type use Permanent. It states full time, which is employment type, but not contract type. Hmm.\n\nsLocation: \"Remote within New Zealand\" maybe location as specific as advert allows: \"Remote within New Zealand\" or \"New Zealand (remote)\". The schema example includes Auckland (hybrid). So use \"Remote within New Zealand\". It also mentions team week in Hamilton each quarter. Could sLocation be \"Remote within New Zealand (team week in Hamilton quarterly)\"? It says as specific as advert allows. The location is remote within NZ. Might include Hamilton? The job is fully remote with quarterly team week in Hamilton. I''d use \"Remote within New Zealand\" perhaps. Maybe \"Remote (New Zealand), quarterly team week in Hamilton\". But sLocation string. The advert''s own line: \"Litware · Remote within New Zealand · Full time\". So sLocation: \"Remote within New Zealand\". Good.\n\nsCompany: Litware (employer, not agency). bAgency false. sCompanyMeta:\nindustry: Agritech? It builds pasture-growth forecasting for dairy farms, using satellite imagery and on-farm sensors. Industry maybe Agritech. Business: \"Litware builds pasture-growth forecasting for dairy farms using satellite imagery and on-farm sensors.\" website_url: not provided. Null.\n\nsJobTitle: Machine Learning Engineer.\n\nsJobRequirement: copy requirements as \"- \" bullet lines, keep wording. From \"What you bring\":\n- 3+ years building ML systems in production\n- Strong Python and PyTorch\n- Experience with time-series or geospatial data\n- AWS (S3, SageMaker or Lambda)\n- A postgraduate degree in a quantitative field is an advantage\n\nNeed be exact. Include these. Maybe also \"What you will do\" are responsibilities not requirements. So just requirements.\n\nsJobSummary: under 80 words plain description no selling. Could mention Litware builds pasture-growth forecasting for dairy farms. Role: train evaluate ship forecasting models in Python; build data pipelines with PyTorch pandas SQL on AWS; productionize and monitor drift; work with agronomists. Fully remote with quarterly team week in Hamilton. Salary 130k-150k. Keep under 80. Count. We can write ~60 words.\n\nsSource: What source? The advert text doesn''t explicitly mention job board. Could be \"Other\" because no URL. But maybe source unknown. Schema requires sSource: \"SEEK | LinkedIn | Company Website | Trade Me Jobs | Other\". We don''t know. Should be \"Other\"? The advert appears as raw text maybe not from board. The source is not stated. The rules say use only information present. If not present null? But sSource is required? It''s in shape with no null allowed, enum. Could use \"Other\" as default. Hmm. It says sSource: \"SEEK | LinkedIn | Company Website | Trade Me Jobs | Other\". The advert doesn''t show source. \"Other\" is correct when not one of known? But if source unknown, maybe \"Other\". Use Other.\n\nsSourceUrl: if URL appears in text. It doesn''t. null.\n\nsTechStack: named technologies only: Python, PyTorch, pandas, SQL, AWS, S3, SageMaker, Lambda. Also maybe \"time-series\" not tech? \"geospatial\" no. \"satellite imagery\" no. \"on-farm sensors\" no. \"ML systems\" maybe ML? Named tech: Python, PyTorch, pandas, SQL, AWS, S3, SageMaker, Lambda. Could include \"AWS\" and services. Include all named.\n\nNeed output JSON only. No markdown.\n\nCheck bAgency false. sCompanyMeta not null. website_url null.\n\nPotential issue: sContractType. The advert says \"Full time\". The allowed enum doesn''t include Full-time. Could use Permanent. I think yes.\n\nLet''s ensure no markdown. JSON object exactly.\n\nNeed maybe industry null? Is \"Agritech\" inferred? Litware builds for dairy farms. Industry is Agritech/Dairy tech. The advert doesn''t explicitly say \"Agritech\", but we can classify industry. Rule: \"Use only information present. Never infer or invent.\" Hmm sCompanyMeta.industry: e.g. Agritech. The company builds pasture-growth forecasting for dairy farms. That''s present. So industry can be \"Agritech\" or \"Dairy technology\". Is that infer? It''s a classification. If strict, maybe \"Agriculture\" or \"Dairy farming technology\". The advert says dairy farms; satellite imagery; on-farm sensors. I''d set industry \"Agritech\" because it''s a direct category. But maybe not stated exactly. Could set \"Agriculture / Dairy\" to avoid inventing. The schema ex…","reasoningChars":8613,"attempt":1,"promptChars":3045,"responseChars":1089,"raw":"{\"sCompany\":\"Litware\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Agritech\",\"business\":\"Litware builds pasture-growth forecasting for dairy farms using satellite imagery and on-farm sensors.\",\"website_url\":null},\"sJobTitle\":\"Machine Learning Engineer\",\"sJobRequirement\":\"- 3+ years building ML systems in production\\n- Strong Python and PyTorch\\n- Experience with time-series or geospatial data\\n- AWS (S3, SageMaker or Lambda)\\n- A postgraduate degree in a quantitative field is an advantage\",\"sContractType\":\"Permanent\",\"sLocation\":\"Remote within New Zealand\",\"sJobSummary\":\"Litware is hiring a Machine Learning Engineer to train, evaluate and ship forecasting models in Python. The role builds data pipelines with PyTorch, pandas and SQL on AWS, puts models into production and monitors drift, and works with agronomists to turn forecasts into decisions farmers trust. Fully remote within New Zealand, with a quarterly team week in Hamilton. Salary is $130k to $150k.\",\"sSource\":\"Other\",\"sSourceUrl\":null,\"sTechStack\":[\"Python\",\"PyTorch\",\"pandas\",\"SQL\",\"AWS\",\"S3\",\"SageMaker\",\"Lambda\"]}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 3, 'extractor', 'validate', 'Check the JSON against the schema', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561769 seconds'), 0, 0, 1, '[{"tool":"json_validator","durationMs":0,"ok":true,"summary":"extracted job: valid, null: sCompanyMeta.website_url, sSourceUrl","detail":{"input":{"data":"{\"sCompany\":\"Litware\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Agritech\",\"business\":\"Litware builds pasture-growth forecasting for dairy farms using satellite imagery and on-farm sensors.\",\"website_url\":null},\"sJobTitle\":\"Machine Learning Engineer\",\"sJobRequirement\":\"- 3+ years building ML systems in production\\n- Strong Python and PyTorch\\n- Experience with time-series or geospatial data\\n- AW… (1089 chars)","schema":"<ZodEffects>","label":"extracted job","requiredNonNull":["sCompany","sJobTitle","sJobSummary"]}}}]', '{"valid":true,"issues":[],"nullFields":["sCompanyMeta.website_url","sSourceUrl"],"missingFields":[]}');
