INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 6, 'main', 'check-fields', 'Check the extracted record', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561769 seconds'), 0, 0, 1, '[]', '{"attempt":1,"required":["sCompany","sJobTitle","sJobSummary","sJobRequirement","sContractType","sSource"],"missing":[],"thin":[],"ok":true}');
