INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561769 seconds'), 10, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561769 seconds'), 2813, 1775, 1, '[]', '{"model":"deepseek-flash","apiMs":2812,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume among two. Job ML Engineer Python PyTorch time-series/geospatial AWS etc. Resume1 AI/LLM applications, Python, AWS Lambda/S3, LLM, evaluation, but not PyTorch, time-series/geospatial, ML production forecasting. Resume2 full-stack, worse. So best is resume1. Need comparative reason naming advert requirement it answers. Rejected resume2 one line lacks. Ensure JSON schema.\n\nNeed sFileName exactly as given. Resume 1 file: Alex_Rivera_CV_AI_Engineer.pdf. sReason: shows production AI/ML-adjacent deployment with Python, AWS Lambda/S3, evaluation/tracing, SQL; closest to ML engineer but lacks PyTorch/time-series. Wait reason should say what this resume has that others do not against advert. It has Python and production AI/LLM pipelines, AWS Lambda/S3, SQL, evaluation sets, which aligns with shipping/monitoring ML systems. But \"best fits\" though no PyTorch. Resume2 has no ML at all. Need perhaps mention it answers \"building ML systems in production\" via deployed LLM feature/evaluation/monitoring? But ML role specifically forecasting models. We must judge overlap. Resume1 is still better due to Python, AWS S3/Lambda, AI production, evaluation, SQL; no PyTorch/time-series. Rejected: full-stack frontend web, lacks ML/Python/PyTorch/time-series/SageMaker. JSON only.\n\nNeed be careful: sReason one sentence. aRejected array.\n\nFinal.","reasoningChars":1386,"raw":"{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"This resume shows production AI/ML-adjacent work in Python with deployed AWS Lambda/S3 services, evaluation sets and tracing for model reliability, and SQL/data-handling experience, which best answers the advert''s need to ship and monitor ML systems in production compared with the other resume.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"It is focused on full-stack React/Next.js/Node.js web development and lacks the advert''s required ML production experience, PyTorch, time-series or geospatial data, and SageMaker work.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_AI_Engineer.pdf","reason":"This resume shows production AI/ML-adjacent work in Python with deployed AWS Lambda/S3 services, evaluation sets and tracing for model reliability, and SQL/data-handling experience, which best answers the advert''s need to ship and monitor ML systems in production compared with the other resume.","rejected":[{"sFileName":"Alex_Rivera_CV_Full_Stack.pdf","sReason":"It is focused on full-stack React/Next.js/Node.js web development and lacks the advert''s required ML production experience, PyTorch, time-series or geospatial data, and SageMaker work."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561767 seconds'), 10299, 3783, 1, '[]', '{"model":"deepseek-flash","apiMs":10299,"finishReason":"stop","reasoning":"Let me draft.\n\nRequirements the advert asks for most clearly: 3+ years building ML systems in production; strong Python and PyTorch; time-series or geospatial data; AWS (S3, SageMaker or Lambda); postgraduate degree advantage.\n\nCandidate has: four years software engineering, last two shipping LLM features in production. Python — yes, tooling, Python mentioned. PyTorch — not in resume. Time series/geospatial — not in resume. AWS Lambda and S3 — yes.\n\nSo can''t claim PyTorch or time-series. Need to be honest. Pick three: production ML systems (LLM features in production, evaluation sets, tracing, monitoring drift-ish?), Python, AWS (Lambda and S3). And the agronomist collaboration bit — working with non-technical people to make forecasts trusted; candidate''s working principle is making software show its working so people trust it.\n\nThree things: \n1. Shipping models/ML systems in production: two years shipping LLM features to production, claims intake handling 2,000 claims a month.\n2. Strong Python: Python tooling reconciling supplier invoices; Python for pipelines... keep honest.\n3. AWS: moved four Node.js services to Lambda, S3.\n\nAlso monitoring drift → evaluation set and tracing cut misrouted claims 9% to 3%. That''s close to monitoring.\n\nIntroduction: two paragraphs. First: working principle, move into tech from hospitality, degree, current role. Two or three sentences, their voice.\n\n\"Make the software show its working, so people can trust what it decides.\" That''s the principle.\n\nSecond paragraph: why this role, name role and company, say what draws them. Specific fact about company: Litware builds pasture-growth forecasting for dairy farms using satellite imagery and on-farm sensors. That''s given. So can mention: forecasts that farmers rely on.\n\nWord limit 300 total. Keep tight.\n\nDraft intro para 1:\n\"I came to software from hospitality. I ran the ordering system at a busy café, taught myself Python to automate the stock count, and went back to study computer science. That is where my working principle came from: make the software show its working, so people can trust what it decides. I now work as a Software Engineer at Humongous Insurance in Auckland, four years in, the last two shipping language model features to production.\"\n\nThat''s ~78 words. Maybe trim.\n\nPara 2:\n\"I am applying for the Machine Learning Engineer role at Litware. Turning satellite imagery and farm sensor readings into a pasture forecast that a farmer can act on is the kind of problem I want to work on, and it is the reason I care about tracing and evaluation: a forecast people cannot check is a forecast they will not use.\"\n\nCheck: no em dash. Good.\n\nsWhyGoodFit: three sentences, one per requirement.\n1. Production ML: \"Litware needs someone who has shipped models into production, and I have spent the last two years doing that: my claims-intake assistant at Humongous Insurance reads customer emails and PDFs and routes over 2,000 claims a month, with a 300-claim evaluation set and step-by-step tracing that cut misrouted claims from 9% to 3%.\" — maybe too long; also that''s addressing \"monitoring drift\" and production.\n2. Python: \"The role is built on Python, which is what I used to write the invoice reconciliation tooling at Margie''s Travel and the evaluation and tracing work on the claims assistant.\" Hmm, the tracing work was likely in TypeScript? Not specified. Careful — resume says \"Software engineer with four years of TypeScript and Python\". Invoice reconciliation tooling was Python — that''s safe.\n3. AWS: \"On the cloud side, I moved four Node.js services to AWS Lambda with GitHub Actions deployments, and I work with S3 and SQL daily.\" SQL daily — resume lists SQL as a skill; \"daily\" is a mild claim. Maybe say \"I work with SQL and PostgreSQL\". Avoid inventing.\n\nTime-series/geospatial — not in resume, skip. Postgrad — skip.\n\nClosing sentence: maybe about working with agronomists — \"I am used to working alongside people who are not engineers and making model behaviour legible to them, which is the part of this role that matters most.\" That adds something.\n\nWatch word count: total 300 max.\n\nLet me count roughly.\n\nIntro p1 (~70), p2 (~65), fit section (~110-120). Total ~255. Good.\n\nWrite final JSON.\n\nAvoid banned words. No em dashes. NZ English (behaviour, organised).\n\nFinal:\n\naIntroduction:\np1: \"I came to software from hospitality. I ran the ordering system at a busy cafe, taught myself Python to automate the stock count, then went back to study computer science. That is where my working principle came from: make the software show its working, so people can trust what it decides. I have a Bachelor of Computer Science and four years as a software engineer, the last two at Humongous Insurance in Auckland shipping language model features to production.\"\n\nUse \"café\" fine.\n\np2: \"I am applying for the Machine Learning Engineer role at Litware. Pasture-growth forecasting for dairy farms, built from satellite imagery and on-farm sensors, is the kind of problem I want to spend my time on, and it is why tracing and evaluation matter to me: a forecast a farmer cannot check is a forecast they will not act on.\"\n\nsWhyGoodFit: \n\"Litware needs someone who has put models into production, and that is what my last two years have been: my claims-intake assistant reads customer emails and PDFs, checks the output against a schema and routes over 2,000 claims a month, with the evaluation set and tracing that took misrouted claims from 9% to 3%. The work runs on Python, which I used to write the invoice reconciliation tooling at Margie''s Travel, and I am comfortable with SQL and pandas-style data work. On the cloud side I moved four Node.js services to AWS Lambda with GitHub Actions deployments, working with S3 along the way. I also spend a lot of my time explaining model behaviour to people who are not engineers, which is the part of helping agronomists that I would enjoy most.\"\n\n\"pandas-style data work\" — hmm, vague. Maybe drop pandas to avoid …","reasoningChars":8336,"resume":"Alex_Rivera_CV_AI_Engineer.pdf","introParagraphs":2,"words":267,"wordLimit":300,"raw":"{\"aIntroduction\": [\"I came to software from hospitality. I ran the ordering system at a busy cafe, taught myself Python to automate the stock count, then went back to study computer science. That is where my working principle came from: make the software show its working, so people can trust what it decides. I have a degree in computer science and four years as a software engineer, the last two at Humongous Insurance in Auckland shipping language model features to production.\", \"I am applying for the Machine Learning Engineer role at Litware. Pasture-growth forecasting for dairy farms, built from satellite imagery and on-farm sensors, is the kind of problem I want to spend my time on. It is why tracing and evaluation matter to me: a forecast a farmer cannot check is a forecast they will not act on.\"], \"sWhyGoodFit\": \"Litware needs someone who has put models into production, and that is what my last two years have been: my claims-intake assistant reads customer emails and PDFs, checks the output against a schema and routes over 2,000 claims a month, with the evaluation set and tracing that took misrouted claims from 9% to 3%. The work runs on Python, which is what I used at Margie''s Travel to write tooling that reconciles supplier invoices, and I work with SQL and PostgreSQL. On the cloud side, I moved four Node.js services to AWS Lambda with GitHub Actions deployments, using S3 along the way. I also spend much of my time explaining model behaviour to people who are not engineers, which is the part of working with agronomists I would enjoy most.\"}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561756 seconds'), 6, 0, 1, '[{"tool":"build_pdf","durationMs":6,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I came to software from hospitality. I ran the ordering system at a busy cafe, taught myself Python to automate the stock count, then went back to study computer science. That is where my working principle came from: make the software show its working, so people can trust what it decides. I have a degree in computer science and four years as a software engineer, the last two at Humongous Insurance… (460 chars)","I am applying for the Machine Learning Engineer role at Litware. Pasture-growth forecasting for dairy farms, built from satellite imagery and on-farm sensors, is the kind of problem I want to spend my time on. It is why tracing and evaluation matter to me: a forecast a farmer cannot check is a forecast they will not act on."]},{"heading":"Why I Am a Good Fit","paragraphs":["Litware needs someone who has put models into production, and that is what my last two years have been: my claims-intake assistant reads customer emails and PDFs, checks the output against a schema and routes over 2,000 claims a month, with the evaluation set and tracing that took misrouted claims from 9% to 3%. The work runs on Python, which is what I used at Margie''s Travel to write tooling that… (741 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"Machine Learning Engineer, Litware"}}}]', '{"pages":1,"sizeBytes":2928,"words":307}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('91b7d489-0381-41d0-bd4c-546ebdddb519', 12, 'cover-letter', 'save-pdf', 'Save the PDF to storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2561756 seconds'), 3, 0, 1, '[{"tool":"storage_put","durationMs":3,"ok":true,"summary":"Litware/Litware_Machine-Learning-Engineer.pdf (3KB)","detail":{"input":{"body":"<2928 bytes>","sStoragePath":"Litware/Litware_Machine-Learning-Engineer.pdf","sFileName":"Litware_Machine-Learning-Engineer.pdf","sContentType":"application/pdf","sKind":"cover-letter","sJobUUID":"2b7e8f05-1e37-4b4d-85d4-91083d7f9838","sNote":"Generated from Alex_Rivera_CV_AI_Engineer.pdf"}}}]', '{"path":"Litware/Litware_Machine-Learning-Engineer.pdf","fileId":"724c7040-9025-4c61-8b9e-bea0c376c7e0","bytes":2928}');
