INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438580 seconds'), 1175, 504, 1, '[]', '{"bIsJobPost":true,"sReason":"It advertises a specific Integration Developer role with responsibilities, required skills, and salary.","sLooksLike":null,"model":"deepseek-flash","apiMs":1174,"finishReason":"stop","reasoning":"We need answer JSON only per schema. Need decide if job ad. Text clearly job advertisement: title, company, location, responsibilities, skills, salary. bIsJobPost true. sReason one short sentence. sLooksLike when not job ad otherwise null. So sLooksLike null. Ensure valid JSON.","reasoningChars":278,"inputChars":815,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\":true,\"sReason\":\"It advertises a specific Integration Developer role with responsibilities, required skills, and salary.\",\"sLooksLike\":null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438579 seconds'), 2923, 1507, 1, '[]', '{"model":"deepseek-flash","apiMs":2923,"finishReason":"stop","reasoning":"The advert is on Trade Me Jobs, posted by employer directly (Wide World Importers).\n\nExtract fields.\n\nsCompany: \"Wide World Importers\"\nbAgency: false\nsCompanyMeta: industry: null? Could be \"Distribution\" — but rules say only info present. The advert says \"distributes homeware from 60 suppliers to retailers\". Industry not stated explicitly as a label. Safer: null? Hmm. The industry could be inferred as distribution/wholesale. Rules say never infer. I''d put null... but arguably \"distributes homeware\" is industry-ish. I''ll set industry to null to be safe? Actually many graders might expect \"Distribution\". The rule: \"Use only information present in the advert. Never infer or invent.\" The advert doesn''t state an industry label. I''ll use null.\n\nbusiness: \"Wide World Importers distributes homeware from 60 suppliers to retailers across New Zealand.\"\nwebsite_url: null (not stated)\n\nsJobTitle: \"Integration Developer\"\nsJobRequirement: bullet lines copied:\n- 3+ years of backend or integration development\n- Node.js and TypeScript\n- AWS serverless services\n- Experience parsing messy partner data: CSV, EDI, XML or email\n- SQL\n\nsContractType: \"Permanent\"\nsLocation: \"Auckland (Mount Wellington)\"\nsJobSummary: under 80 words.\nsSource: \"Trade Me Jobs\"\nsSourceUrl: null\nsTechStack: [\"Node.js\", \"TypeScript\", \"REST\", \"AWS Lambda\", \"AWS SQS\", \"AWS S3\", \"SQL\", \"CSV\", \"EDI\", \"XML\", \"serverless\"] — named technologies only. CSV/EDI/XML are data formats; maybe include. I''ll include them as data formats... they''re arguably technologies. I''ll keep them modest: Node.js, TypeScript, REST, AWS Lambda, AWS SQS, AWS S3, SQL, XML, CSV, EDI.","reasoningChars":1630,"attempt":1,"promptChars":3117,"responseChars":1135,"raw":"{\"sCompany\": \"Wide World Importers\", \"bAgency\": false, \"sCompanyMeta\": {\"industry\": null, \"business\": \"Wide World Importers distributes homeware from 60 suppliers to retailers across New Zealand, connecting its warehouse, ERP and customers'' ordering systems.\", \"website_url\": null}, \"sJobTitle\": \"Integration Developer\", \"sJobRequirement\": \"- 3+ years of backend or integration development\\n- Node.js and TypeScript\\n- AWS serverless services\\n- Experience parsing messy partner data: CSV, EDI, XML or email\\n- SQL\", \"sContractType\": \"Permanent\", \"sLocation\": \"Auckland (Mount Wellington)\", \"sJobSummary\": \"Build and maintain integrations in Node.js and TypeScript for Wide World Importers, a homeware distributor. Design REST and event-driven interfaces with suppliers and retailers, run serverless workloads on AWS Lambda, SQS and S3, monitor integrations, fix failures quickly and document every interface. Salary $110k to $125k plus a performance bonus.\", \"sSource\": \"Trade Me Jobs\", \"sSourceUrl\": null, \"sTechStack\": [\"Node.js\", \"TypeScript\", \"REST\", \"event-driven\", \"AWS Lambda\", \"AWS SQS\", \"AWS S3\", \"SQL\", \"CSV\", \"EDI\", \"XML\"]}"}');
