INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438576 seconds'), 29, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438576 seconds'), 5406, 2327, 1, '[]', '{"model":"deepseek-flash","apiMs":5406,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume for Integration Developer at Wide World Importers. Need compare. Two resumes: Resume 1 AI Engineer, Resume 2 Full Stack. Job requires Node.js TypeScript, AWS serverless Lambda SQS S3, parsing messy partner data CSV EDI XML email, SQL, REST/event-driven, integrations. Resume1 has TypeScript, Node.js, AWS Lambda and S3, parsing messy emails/PDFs, JSON schema, SQL, Python, LLM. But lacks SQS, EDI/XML/CSV? Mentions emails/PDFs, messy business text. Has Node services to Lambda. Resume2 full-stack has TypeScript, Node.js, REST APIs, AWS Lambda/S3, PostgreSQL SQL, contract tests, but no event-driven SQS, no messy partner data CSV/EDI/XML/email, no integration focus; frontend-heavy. Which best? Resume1 more aligned to parsing messy partner data (emails/PDFs) and backend/integration? It has Node.js and AWS Lambda, TypeScript, SQL. Resume2 has REST APIs and partner integrations? It says \"Designed typed REST APIs in Node.js and PostgreSQL for the portal and two partner integrations.\" That directly mentions partner integrations. But lacks messy data parsing and event-driven/SQS. Resume1 has claims-intake assistant parsing emails/PDFs, data validation, routing, Lambda, but not REST/event-driven, SQS. Also title AI Engineer, LLM focus, not integration developer. The job says \"Experience parsing messy partner data: CSV, EDI, XML or email\" Resume1 has email/PDF parsing. Resume2 has partner integrations but not messy data, and more frontend. Also job backend/integration. Resume1 has backend Node services to Lambda and data parsing. Resume2 has typed REST APIs and partner integrations, Node, TypeScript, SQL, AWS Lambda/S3. Which better? Need decide.\n\nLet''s inspect requirements:\n- 3+ years backend or integration development: Resume1 four years TypeScript/Python, last two LLM; built claims-intake assistant, moved Node services to Lambda. Some backend/integration? Resume2 full-stack, designed REST APIs for partner integrations, moved Node services. Both.\n- Node.js and TypeScript: both yes.\n- AWS serverless services: Resume1 Lambda and S3. Resume2 Lambda and S3. Neither SQS.\n- Experience parsing messy partner data: CSV, EDI, XML or email: Resume1 explicitly LLM reads customer emails and PDFs, validates JSON schemas, over 2000 claims/month. Resume2 no messy data.\n- SQL: both PostgreSQL.\nTechnologies: REST, event-driven, AWS Lambda, AWS SQS, AWS S3, SQL, CSV, EDI, XML. Resume1 no REST? Skills include REST, yes. No event-driven/SQS/CSV/EDI/XML but email/PDF. Resume2 has REST, no event-driven/SQS/CSV/EDI/XML. Resume2 mentions two partner integrations but not parsing messy data. Resume1 mentions AWS Lambda and S3 and emails. It seems Resume1 better for integration data parsing, though AI focus. Need produce reason comparative: what Resume1 shows others do not: hands-on parsing unstructured partner/customer data (emails/PDFs) into validated JSON and routing at scale, plus Node/TypeScript on Lambda/S3, matching messy data parsing and serverless. Rejected resume2: full-stack frontend-heavy; lacks messy partner data parsing and event-driven/SQS integration work; partner REST APIs but no CSV/EDI/XML/email ingestion.\n\nNeed ensure JSON valid with file names exactly. sFileName: Alex_Rivera_CV_AI_Engineer.pdf? The file name in resume: \"Alex_Rivera_CV_AI_Engineer.pdf (AI engineering and LLM applications)\"? They say \"File: Alex_Rivera_CV_AI_Engineer.pdf (AI engineering and LLM applications)\" Probably file name is Alex_Rivera_CV_AI_Engineer.pdf. For rejected: Alex_Rivera_CV_Full_Stack.pdf. Need include one-line reasons.\n\nNeed maybe if sReason should be one sentence. aRejected list. JSON only. No markdown. Ensure no extra. Use exact.","reasoningChars":3709,"raw":"{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"This resume shows direct experience parsing messy partner-style data — customer emails and PDFs — into validated structured JSON at scale, plus Node.js services deployed to AWS Lambda and S3, which answers the advert''s messy-data ingestion and serverless requirements more than the other resume.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"It is frontend-heavy full-stack work with partner REST APIs, but lacks the advert''s messy CSV/EDI/XML/email parsing and event-driven SQS integration experience.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_AI_Engineer.pdf","reason":"This resume shows direct experience parsing messy partner-style data — customer emails and PDFs — into validated structured JSON at scale, plus Node.js services deployed to AWS Lambda and S3, which answers the advert''s messy-data ingestion and serverless requirements more than the other resume.","rejected":[{"sFileName":"Alex_Rivera_CV_Full_Stack.pdf","sReason":"It is frontend-heavy full-stack work with partner REST APIs, but lacks the advert''s messy CSV/EDI/XML/email parsing and event-driven SQS integration experience."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438571 seconds'), 28681, 8553, 1, '[]', '{"model":"deepseek-flash","apiMs":28679,"finishReason":"stop","reasoning":"We need answer JSON only. Need write two sections cover letter. Must adhere schema. Need 300 words total across both. NZ English. No em dashes, no headings, no markdown, no bullets. aIntroduction two paragraphs (array of strings). sWhyGoodFit three-four sentences prose, no bullet points. Need pick advert asks most clearly: 3+ years backend/integration; Node.js and TypeScript; AWS serverless services; parsing messy partner data CSV EDI XML/email; SQL. Need three requirements most clearly. Could choose Node.js/TypeScript backend integration, AWS serverless, parsing messy partner data. Maybe SQL too but only three. Need evidence from resume/highlights. Avoid resume duty list. Must name requirement then specific thing done.\n\nNeed total <=300 words. Let''s draft carefully.\n\naIntroduction paragraph 1: background from standing highlights: working principle, move into tech, degree, current role. Keep voice. Two/three sentences.\n\n\"Make the software show its working, so people can trust what it decides. That principle took me from running a café''s ordering system, teaching myself Python to automate stock counts, to a computer science degree in 2020. I am now a Software Engineer at Humongous Insurance in Auckland, where I have spent four years building software, the last two on language model features in production.\" Word count ~66. Maybe \"I came to software from hospitality...\" Keep voice.\n\nParagraph 2: Why this role. Name role and company, say plainly what draws them. Mention specific company fact only if given: Wide World Importers distributes homeware from 60 suppliers to retailers across NZ, connecting warehouse, ERP and customers'' ordering systems. We can mention that fact. Need no invented. \"The Integration Developer role at Wide World Importers draws me because it sits between systems that must agree: 60 suppliers, your warehouse, ERP and retailers'' ordering systems. I like work where a clean interface lets everyone trust the numbers.\" Good.\n\nsWhyGoodFit: 3-4 sentences. Requirement 1: \"The role needs 3+ years of backend or integration development, and I have four years building and connecting services, including four Node.js services moved to AWS Lambda.\" Actually moved four Node services to Lambda covers AWS too. Could separate. Sentence 1: backend/integration experience. Sentence 2: Node.js and TypeScript. \"You ask for Node.js and TypeScript; I use TypeScript daily and have built booking and itinerary features in React, Next.js and PostgreSQL and moved Node.js services to Lambda.\" Sentence 3: AWS serverless. \"The serverless work at Humongous Insurance used AWS Lambda, and I deployed through GitHub Actions.\" Sentence 4: parsing messy partner data. \"For messy partner data, I built a claims-intake assistant that reads customer emails and PDFs..., validates into JSON schemas, routes 2000 claims/month.\" Need maybe SQL: \"I also use SQL and PostgreSQL...\" But that may be fourth. Only 3-4. Maybe combine Node.js/TypeScript with backend/integration. Then AWS serverless. Then messy data. Close maybe SQL? If four sentences, can include SQL in close sentence if adds. But close only if adds. Could include SQL with messy data sentence. But total words.\n\nNeed ensure not generic. Use advert''s plain words: \"backend or integration development\", \"Node.js and TypeScript\", \"AWS serverless services\", \"parsing messy partner data\", \"SQL\". We can write:\n\n\"The role needs three or more years of backend or integration work, and I have four years building services that connect to each other, most recently moving four Node.js services at Humongous Insurance to AWS Lambda.\" This covers backend/integration and AWS Lambda maybe.\n\n\"Node.js and TypeScript are my daily tools, and I have used them with REST and PostgreSQL on booking systems as well as on serverless workloads.\" Good.\n\n\"AWS serverless services are central to what you do, and I have run Lambda in production and deployed it with GitHub Actions.\" Maybe S3? Resume says AWS Lambda and S3. Advert asks Lambda, SQS, S3. We only have Lambda and S3. Could say \"Lambda and S3\" not SQS. Avoid claiming SQS. \"I have run Lambda and S3 in production...\" Good.\n\n\"You also need to parse messy partner data, which is what I did for claims: an LLM read customer emails and PDFs, validated them against JSON schemas and routed over 2,000 claims a month.\" This covers email/PDF, maybe not CSV/EDI/XML. But messy partner data. Fine.\n\nNeed SQL? If not mention, maybe okay because three things. But advert asks SQL. Could add in fourth? \"I use SQL and PostgreSQL...\" But then 4 sentences. sWhyGoodFit can be three or four. If four, close maybe no separate close. Need each sentence requirement. Maybe incorporate SQL into Node/TS sentence: \"Node.js and TypeScript are my daily tools, and I use them with SQL and PostgreSQL...\" That covers Node, TS, SQL. Then AWS serverless. Then messy data. That''s three requirements? The advert''s three most clear: Node/TS, AWS serverless, messy data. But 3+ years backend/integration is also clear. Hmm.\n\nMaybe sentence 1: 3+ years backend/integration + Node/TS. Sentence 2: AWS serverless. Sentence 3: messy partner data + SQL? But SQL separate. Sentence 4: SQL. That''s four. Could be:\n\n\"With four years in backend and integration work, I bring the three or more years you ask for, and I have built in Node.js and TypeScript throughout.\" \n\"Your serverless workloads run on AWS, which matches my production work moving four Node.js services to Lambda and S3 with GitHub Actions deployments.\" \n\"For messy partner data, I built a claims-intake assistant where an LLM read customer emails and PDFs, validated the output against JSON schemas, and routed over 2,000 claims a month.\" \n\"SQL is part of my daily work through PostgreSQL, where I have reconciled supplier invoices against bookings with Python tooling.\" \nThis is four sentences. Each names requirement and evidence. Sentence 4 evidence: wrote Python tooling reconciles supplier invoices against bookings, but says SQL daily through …","reasoningChars":28195,"resume":"Alex_Rivera_CV_AI_Engineer.pdf","introParagraphs":2,"words":180,"wordLimit":300,"raw":"{\"aIntroduction\":[\"Make the software show its working, so people can trust what it decides. That principle took me from running a café''s ordering system, teaching myself Python to automate stock counts, to a computer science degree in 2020. I now work as a Software Engineer at Humongous Insurance in Auckland, four years into building software and two years into shipping language model features to production.\",\"The Integration Developer role at Wide World Importers appeals because it joins systems that must agree: 60 suppliers, your warehouse, ERP and customers'' ordering systems. I want to build the interfaces that keep those numbers straight.\"],\"sWhyGoodFit\":\"The role asks for three or more years of backend or integration development, and I have four years building services with Node.js, TypeScript and SQL. The AWS serverless services you use match my production work moving four Node.js services to Lambda, using S3, and deploying through GitHub Actions. For parsing messy partner data, I built a claims-intake assistant where a language model read customer emails and attached documents, validated the output against schemas, and routed over 2,000 claims a month.\"}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a2ee0f46-3755-4a68-9c7e-47cde7604cf1', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1438542 seconds'), 33, 0, 1, '[{"tool":"build_pdf","durationMs":33,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["Make the software show its working, so people can trust what it decides. That principle took me from running a café''s ordering system, teaching myself Python to automate stock counts, to a computer science degree in 2020. I now work as a Software Engineer at Humongous Insurance in Auckland, four years into building software and two years into shipping language model features to production.","The Integration Developer role at Wide World Importers appeals because it joins systems that must agree: 60 suppliers, your warehouse, ERP and customers'' ordering systems. I want to build the interfaces that keep those numbers straight."]},{"heading":"Why I Am a Good Fit","paragraphs":["The role asks for three or more years of backend or integration development, and I have four years building services with Node.js, TypeScript and SQL. The AWS serverless services you use match my production work moving four Node.js services to Lambda, using S3, and deploying through GitHub Actions. For parsing messy partner data, I built a claims-intake assistant where a language model read custom… (509 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"Integration Developer, Wide World Importers"}}}]', '{"pages":1,"sizeBytes":2617,"words":220}');
