INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a792e88d-66f1-4b18-9b51-0aad41d99551', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401780 seconds'), 1272, 522, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an AI Developer role, responsibilities, requirements, location, salary, and how to apply.","sLooksLike":null,"model":"deepseek-flash","apiMs":1271,"finishReason":"stop","reasoning":"We need answer JSON only. Need decide if job ad. Yes it''s job advertisement. Need schema: bIsJobPost true, sReason one short sentence, sLooksLike null. Must return JSON only. Ensure valid JSON.","reasoningChars":193,"inputChars":968,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\": true, \"sReason\": \"It describes an AI Developer role, responsibilities, requirements, location, salary, and how to apply.\", \"sLooksLike\": null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a792e88d-66f1-4b18-9b51-0aad41d99551', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401779 seconds'), 2576, 1293, 1, '[]', '{"model":"deepseek-flash","apiMs":2576,"finishReason":"stop","reasoning":"The advert is from an agency (Proseware Talent). So sCompany = \"Proseware Talent\", bAgency true, sCompanyMeta = null.\n\nContract type: not stated → Permanent.\n\nLocation: Auckland (hybrid) — advert says \"Auckland\" and \"Hybrid, 3 days in the office\". So \"Auckland (hybrid)\".\n\nSource: not stated → not SEEK... Source field options: SEEK | LinkedIn | Company Website | Trade Me Jobs | Other. No URL given. Use \"Other\" probably.\n\nTech stack: TypeScript, Node.js, vector databases, RAG, LLM. Named technologies: TypeScript, Node.js. \"vector databases\" is generic, not named. Maybe include \"RAG\"? It''s a technique. Hmm, named technologies only. TypeScript, Node.js. Could include \"LLMs\"? Not a named technology really. I''ll include TypeScript, Node.js.\n\nJob requirements: copy the bullet lines from \"What our client is looking for\".\n\nSummary under 80 words.\n\nSalary mentioned in title but no field for it.\n\nsSourceUrl null.","reasoningChars":915,"attempt":1,"promptChars":3270,"responseChars":995,"raw":"{\"sCompany\":\"Proseware Talent\",\"bAgency\":true,\"sCompanyMeta\":null,\"sJobTitle\":\"AI Developer (LLM Applications)\",\"sJobRequirement\":\"- 3+ years of software development, with recent hands-on LLM work\\n- TypeScript and Node.js\\n- Experience with retrieval (RAG) and vector databases\\n- Comfortable working directly with customers\",\"sContractType\":\"Permanent\",\"sLocation\":\"Auckland (hybrid, 3 days in the office)\",\"sJobSummary\":\"An AI Developer role with an Auckland SaaS company in property management, recruited by Proseware Talent. The developer joins the product team to add AI features across the platform, including automated maintenance-request triage, lease document Q&A and a natural-language reporting assistant. Work includes building LLM features, tool-calling agents, retrieval over customer documents, and monitoring model quality in production. Hybrid, three days in the office.\",\"sSource\":\"Other\",\"sSourceUrl\":null,\"sTechStack\":[\"TypeScript\",\"Node.js\",\"LLM\",\"RAG\",\"vector databases\"]}"}');
