INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a792e88d-66f1-4b18-9b51-0aad41d99551', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401777 seconds'), 17, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a792e88d-66f1-4b18-9b51-0aad41d99551', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401777 seconds'), 2270, 1614, 1, '[]', '{"model":"deepseek-flash","apiMs":2270,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume. Compare resumes. Both same person? Resume 1 AI Engineer, resume 2 Full Stack. Job AI Developer LLM Applications. Requirements TypeScript Node LLM RAG vector db, customer work, 3+ years, recent hands-on LLM. Resume 1 clearly has LLM production, tool calling, structured outputs, retrieval pgvector, evaluation/tracing. Resume 2 full-stack lacks LLM work except side project retrieval, but not recent hands-on LLM role. So choose resume 1. Need sFileName exactly \"Alex_Rivera_CV_AI_Engineer.pdf\". sReason comparative one sentence naming advert requirement. Rejected resume 2 one-line. Need JSON only. Ensure valid JSON.","reasoningChars":666,"raw":"{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"This resume shows recent hands-on production LLM work—claims-intake assistant, tool calling, structured outputs, evaluation/tracing, and pgvector retrieval—directly matching the advert''s LLM, RAG, vector database, TypeScript/Node.js and production model-quality requirements, while the other resume is aimed at full-stack/frontend work and only mentions retrieval in a side project.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"It lacks recent professional LLM application experience and only shows retrieval in a side project, so it does not match the advert''s core LLM, agents, RAG and production model-quality requirements.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_AI_Engineer.pdf","reason":"This resume shows recent hands-on production LLM work—claims-intake assistant, tool calling, structured outputs, evaluation/tracing, and pgvector retrieval—directly matching the advert''s LLM, RAG, vector database, TypeScript/Node.js and production model-quality requirements, while the other resume is aimed at full-stack/frontend work and only mentions retrieval in a side project.","rejected":[{"sFileName":"Alex_Rivera_CV_Full_Stack.pdf","sReason":"It lacks recent professional LLM application experience and only shows retrieval in a side project, so it does not match the advert''s core LLM, agents, RAG and production model-quality requirements."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a792e88d-66f1-4b18-9b51-0aad41d99551', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401774 seconds'), 10253, 3790, 1, '[]', '{"model":"deepseek-flash","apiMs":10251,"finishReason":"stop","reasoning":"Let me draft.\n\nIntroduction paragraph 1: working principle, move into tech, degree, current role. Two-three sentences, keep voice.\n\nParagraph 2: why this role, name role and company (Proseware Talent is the agency; the client is unnamed SaaS company in property management). Can I mention the client fact? The advert gives a fact: Auckland SaaS company in property management, AI features across the platform including maintenance-request triage, lease document Q&A, natural-language reporting. That is a fact given about the company (the client). Hmm, \"Mention something specific about the company ONLY if you were given a fact about it, and never invent one.\" We were given facts about the client company''s product and location. But instruction above says \"No verified fact about the company is available. Do not write a sentence about it.\" That refers to Proseware Talent. Careful. I think safest: name the role and the company (Proseware Talent) and say what draws them to it, referencing the work described (AI features across a property management platform) — that''s from the advert, not invented. Hmm, but risk. The advert summary describes the role''s work: maintenance-request triage, lease document Q&A, natural-language reporting. Saying that draws them is fine as it''s about the role. I''ll frame it around the role''s content rather than a company claim. Actually mentioning \"property management platform\" is a fact from the advert about the client. I''ll keep it light and tie it to the role work.\n\nWhy good fit: three requirements most clearly:\n1. 3+ years software development with recent hands-on LLM work.\n2. TypeScript and Node.js.\n3. Retrieval (RAG) and vector databases.\n4. Comfortable working directly with customers. — pick three: which three asked most clearly? The first three named in \"what they ask for\" list order: 3+ years with recent hands-on LLM work; TypeScript and Node.js; retrieval (RAG) and vector databases. Hmm, comfortable working directly with customers is a soft one. I''ll pick LLM work, TypeScript/Node, RAG/vector databases. Maybe combine customer? Only three sentences.\n\nEvidence:\n- LLM: claims-intake assistant, 2,000 claims/month; evaluation set and tracing cut misroutes 9% to 3%. Also monitoring model quality in production.\n- TypeScript and Node.js: four Node.js services to AWS Lambda; TypeScript across four years.\n- RAG/vector: recipe planner side project, retrieval over 5,000 recipes with pgvector.\n\nAlso advert mentions tool-calling agents. Could mention tool calling but keep to 3.\n\nWord limit 300 total. Keep tight.\n\nDraft:\n\naIntroduction para 1: \"I am a software engineer at Humongous Insurance in Auckland, where I have spent the last two years shipping large language model features to production. I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count, then went back to study. My working principle is simple: make the software show its working so people can trust what it decides.\"\n\nHmm \"make the software show its working\" keep voice. That''s ~75 words. Fine but total limit 300.\n\nPara 2: \"I would like to apply for the AI Developer (LLM Applications) role advertised by Proseware Talent. The work described, reading maintenance requests, answering questions about lease documents and letting people ask for reports in plain language, is the kind of problem I enjoy: turning messy text into something a system can check and act on. I have no fact about the client to go on beyond that, so my interest is in the work itself.\" — Hmm, that last sentence is awkward and meta. Better to just say what draws them. Avoid mentioning no fact.\n\nPara 2: \"I would like to apply for the AI Developer role with Proseware Talent. The work described, triaging maintenance requests, answering questions from lease documents and building a reporting assistant people can talk to, is the work I already do: turning messy text into checked, structured data that a product can act on.\"\n\nWait, \"answering questions from lease documents\" is retrieval — that''s the side project, not current role. Fine to say it''s the work I want to do. Say \"is the work I want to keep doing\".\n\nsWhyGoodFit:\n\n\"The role asks for recent hands-on LLM work, and mine is in production: I built a claims-intake assistant that reads customer emails and PDFs, validates the output against JSON schemas, and routes over 2,000 claims a month. The advert also asks for TypeScript and Node.js, which is what I use day to day; I moved four Node.js services to AWS Lambda with GitHub Actions deployments. For retrieval over customer documents I built a recipe planner that searches 5,000 recipes stored in pgvector, with a model that explains each suggestion. Working directly with customers is familiar too...\" — that would be a 4th. Instruction: close with one sentence only if it adds something the first three did not. Could close with customer sentence. But word count. Let''s keep three or four. I''ll add a short closing? Maybe skip to stay under 300 words.\n\nLet me count words.\n\nIntro p1: \n\"I am a software engineer at Humongous Insurance in Auckland, where I have spent the last two years shipping language model features to production. (28ish) I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count, then went back to study computer science. (~32) My working principle is simple: make the software show its working, so people can trust what it decides. (~18)\" Total ~78.\n\np2: \"I would like to apply for the AI Developer role advertised by Proseware Talent. (~15) The work described, triaging maintenance requests, answering questions from lease documents and building a reporting assistant people can talk to, is the work I want to keep doing: turning messy text into checked, structured data a product can act on. (~42)\" Total ~57.\n\nGood fit: 3 sentences ~ 35 each = 105-115. Total ~245. Good, room for closing sentence maybe.\n\nAvoid …","reasoningChars":8540,"resume":"Alex_Rivera_CV_AI_Engineer.pdf","introParagraphs":2,"words":249,"wordLimit":300,"raw":"{\n  \"aIntroduction\": [\n    \"I am a software engineer at Humongous Insurance in Auckland, where I have spent the last two years shipping language model features to production. I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count, then went back to study computer science. My working principle is simple: make the software show its working, so people can trust what it decides.\",\n    \"I would like to apply for the AI Developer role advertised by Proseware Talent. The work described, triaging maintenance requests, answering questions from lease documents and building a reporting assistant people can talk to, is the work I want to keep doing: turning messy text into checked, structured data a product can act on.\"\n  ],\n  \"sWhyGoodFit\": \"The advert asks for recent hands-on work with language models, and mine runs in production: I built a claims-intake assistant that reads customer emails and PDFs, checks its output against JSON schemas, and routes more than 2,000 claims a month. It also asks for TypeScript and Node.js, which is my daily work, and I moved four Node.js services onto AWS Lambda, deployed through GitHub Actions. Retrieval is not new to me either: my recipe planner side project searches 5,000 recipes held in a vector database, with a model that explains each suggestion. The role also covers monitoring model quality in production, which is the part I like most, and a 300-claim evaluation set with step-by-step tracing cut misrouted claims from 9% to 3%.\"\n}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('a792e88d-66f1-4b18-9b51-0aad41d99551', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-401764 seconds'), 24, 0, 1, '[{"tool":"build_pdf","durationMs":23,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I am a software engineer at Humongous Insurance in Auckland, where I have spent the last two years shipping language model features to production. I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count, then went back to study computer science. My working principle is simple: make the software show its working, so people … (426 chars)","I would like to apply for the AI Developer role advertised by Proseware Talent. The work described, triaging maintenance requests, answering questions from lease documents and building a reporting assistant people can talk to, is the work I want to keep doing: turning messy text into checked, structured data a product can act on."]},{"heading":"Why I Am a Good Fit","paragraphs":["The advert asks for recent hands-on work with language models, and mine runs in production: I built a claims-intake assistant that reads customer emails and PDFs, checks its output against JSON schemas, and routes more than 2,000 claims a month. It also asks for TypeScript and Node.js, which is my daily work, and I moved four Node.js services onto AWS Lambda, deployed through GitHub Actions. Retri… (739 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"AI Developer (LLM Applications), Proseware Talent"}}}]', '{"pages":1,"sizeBytes":2957,"words":289}');
