INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('ac7338a8-0d11-4b00-b48f-9f910f253adc', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462580 seconds'), 1126, 504, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an AI Engineer role, responsibilities, requirements, employer, and benefits.","sLooksLike":null,"model":"deepseek-flash","apiMs":1126,"finishReason":"stop","reasoning":"We need answer JSON only. Need decide if job advertisement. Clearly yes. Need schema. sLooksLike null. sReason short. Ensure valid JSON.","reasoningChars":136,"inputChars":994,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\": true, \"sReason\": \"It describes an AI Engineer role, responsibilities, requirements, employer, and benefits.\", \"sLooksLike\": null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('ac7338a8-0d11-4b00-b48f-9f910f253adc', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462579 seconds'), 7558, 2521, 1, '[]', '{"model":"deepseek-flash","apiMs":7558,"finishReason":"stop","reasoning":"We need answer JSON only. Need extract. Advert: AI Engineer, Fabrikam, Wellington (hybrid), Permanent full time. Not agency. sCompany Fabrikam. bAgency false. sCompanyMeta: industry? document-processing software? Not explicitly industry maybe \"Document-processing software\" or null. Business: Fabrikam builds document-processing software for NZ councils and utilities. Website null (not in text). sJobTitle \"AI Engineer\". Requirements copy as bullet lines from \"What we are looking for\" plus nice to have? Rules: sJobRequirement copy requirements as \"- \" bullet lines. Keep advert wording. Could include requirements section and nice to have? Probably include all. Need exact wording. Requirements:\n- 3+ years of software engineering experience\n- Production experience with LLM APIs and structured outputs\n- Strong Python; TypeScript is a plus\n- Experience with evaluation and monitoring of ML or LLM systems\n- SQL and PostgreSQL\nNice to have: retrieval-augmented generation, pgvector, AWS Lambda.\nShould include nice to have maybe as bullet \"- Nice to have: retrieval-augmented generation, pgvector, AWS Lambda.\" That''s ok. sContractType Permanent. sLocation \"Wellington (hybrid)\" as advert. sJobSummary under 80 words plain: Fabrikam seeks AI Engineer to build LLM-powered extraction pipelines... etc. sSource? The advert doesn''t state source. It looks maybe from company website? But rules: source must be one of. We don''t know. If advert text provided no URL. Could be Company Website? It has no job board. But sSource required? Shape says string. Need decide. The source isn''t stated. In previous tasks maybe sSource can be \"Other\" if unknown. The instructions: \"sSource\": \"SEEK | LinkedIn | Company Website | Trade Me Jobs | Other\". Use only info present. Since no source info, maybe \"Other\". But can infer from formatting? Advert has no SEEK branding. Likely company website. But \"Never infer\". So sSource \"Other\" or null? Schema says string no null. I''d use \"Other\". sSourceUrl null. sTechStack: Python, TypeScript, AWS, LLM APIs, structured outputs, SQL, PostgreSQL, retrieval-augmented generation, pgvector, AWS Lambda. Are \"LLM APIs\" named tech? It''s technology category, not named specific. But maybe include \"LLM APIs\"? Named technologies only (languages, frameworks, cloud, tools, test frameworks). \"AWS\" yes cloud, Python, TypeScript, SQL, PostgreSQL, pgvector, AWS Lambda, retrieval-augmented generation? RAG is technique, maybe not. Structured outputs not named tech. Evaluation and monitoring not. Could include \"LLM APIs\" maybe generic. I''d include Python, TypeScript, AWS, SQL, PostgreSQL, pgvector, AWS Lambda. Maybe also LLM APIs? It says named technologies only, \"LLM APIs\" not a named tech. RAG maybe not named technology. But \"retrieval-augmented generation\" is a technique, not named technology. Could include? The tech stack should be named technologies only. I''ll include Python, TypeScript, AWS, SQL, PostgreSQL, pgvector, AWS Lambda. Maybe \"LLM APIs\" is not specific. \"structured outputs\" no. \"ML\" no.\n\nNeed ensure JSON with boolean true/false not string. sCompanyMeta industry: maybe \"Software\" or \"Document-processing software\"? The example \"Agritech, Banking, Healthcare\". Advert says builds document-processing software for councils and utilities. Industry could be \"Software\" or \"Document-processing software\". Since industry example, \"Software\" maybe. But we can use null if not stated? It is stated: document-processing software. The industry is document processing / software. I''d put \"Document-processing software\" maybe. Business one sentence: \"Fabrikam builds document-processing software for New Zealand councils and utilities.\" Website null.\n\nsJobSummary under 80 words. Need plain description. \"Fabrikam is hiring an AI Engineer in Wellington (hybrid) on a permanent full-time basis. The role builds LLM-powered extraction pipelines that convert unstructured documents into validated structured data. It involves prompt design, tool calls, JSON schemas, evaluation sets, tracing, and production services in Python and TypeScript on AWS.\" Word count: Fabrikam(1) is2 hiring3 an4 AI5 Engineer6 in7 Wellington8 hybrid9 on10 a11 permanent12 full-time13 basis14. The15 role16 builds17 LLM-powered18 extraction19 pipelines20 that21 convert22 unstructured23 documents24 into25 validated26 structured27 data28. It29 involves30 prompt31 design32, tool33 calls34, JSON35 schemas36, evaluation37 sets38, tracing39, and40 production41 services42 in43 Python44 and45 TypeScript46 on47 AWS48. Under 80. Good.\n\nsJobRequirement as string with \\n bullets. Need exactly:\n\"- 3+ years of software engineering experience\\n- Production experience with LLM APIs and structured outputs\\n- Strong Python; TypeScript is a plus\\n- Experience with evaluation and monitoring of ML or LLM systems\\n- SQL and PostgreSQL\\n- Nice to have: retrieval-augmented generation, pgvector, AWS Lambda.\"\n\nShould \"Nice to have\" be included? Yes maybe.\n\nsLocation: \"Wellington (hybrid)\" from advert. Or \"Wellington\". More specific with hybrid. The shape example \"Auckland (hybrid)\". I''ll use \"Wellington (hybrid)\".\n\nsSource: \"Other\". sSourceUrl: null.\n\nNeed final JSON only, no markdown. Ensure valid JSON. Use double quotes. Boolean false.\n\nCheck bAgency: false. sCompanyMeta when bAgency false includes. Good.\n\nPotential issue: sCompanyMeta.industry. Advert does not explicitly say industry. It says builds document-processing software for NZ councils and utilities. That implies industry maybe \"Software\" or \"Document-processing software\". The rule: Use only info present, never infer. The phrase \"document-processing software\" is present, so industry can be \"Document-processing software\". Good.\n\nsCompanyMeta.business: one sentence on what company does. Present.\n\nsCompanyMeta.website_url: null.\n\nsTechStack: Could include \"AWS Lambda\", \"pgvector\", \"PostgreSQL\", \"SQL\", \"Python\", \"TypeScript\", \"AWS\". Maybe \"retrieval-augmented generation\" is named technique, not technology. No.\n\nNeed maybe incl…","reasoningChars":6296,"attempt":1,"promptChars":3296,"responseChars":1109,"raw":"{\"sCompany\":\"Fabrikam\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Document-processing software\",\"business\":\"Fabrikam builds document-processing software for New Zealand councils and utilities.\",\"website_url\":null},\"sJobTitle\":\"AI Engineer\",\"sJobRequirement\":\"- 3+ years of software engineering experience\\n- Production experience with LLM APIs and structured outputs\\n- Strong Python; TypeScript is a plus\\n- Experience with evaluation and monitoring of ML or LLM systems\\n- SQL and PostgreSQL\\n- Nice to have: retrieval-augmented generation, pgvector, AWS Lambda.\",\"sContractType\":\"Permanent\",\"sLocation\":\"Wellington (hybrid)\",\"sJobSummary\":\"Fabrikam is hiring an AI Engineer in Wellington (hybrid) on a permanent full-time basis. The role builds LLM-powered extraction pipelines that convert unstructured documents into validated structured data. It involves prompt design, tool calls, JSON schemas, evaluation sets, tracing, and production services in Python and TypeScript on AWS.\",\"sSource\":\"Other\",\"sSourceUrl\":null,\"sTechStack\":[\"Python\",\"TypeScript\",\"AWS\",\"SQL\",\"PostgreSQL\",\"pgvector\",\"AWS Lambda\"]}"}');
