INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('ac7338a8-0d11-4b00-b48f-9f910f253adc', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462572 seconds'), 4, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('ac7338a8-0d11-4b00-b48f-9f910f253adc', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462572 seconds'), 2634, 1698, 1, '[]', '{"model":"deepseek-flash","apiMs":2634,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume. Two resumes same person tailored different. Job AI Engineer LLM pipelines. Resume1 AI Engineer has LLM production, JSON schemas, evaluation sets, tracing, Python/TypeScript, pgvector, Lambda, PostgreSQL. Resume2 full-stack lacks LLM API structured outputs/evaluation/monitoring. Must return JSON with sFileName exact, sReason comparative, aRejected with one-line reason. Need ensure valid JSON. Use exact file names. sReason one sentence. Rejected list one item.\n\nNeed be careful: \"Say what this resume has that the others do not, naming the advert''s requirement it answers.\" So reason mention production LLM APIs and structured outputs, evaluation/tracing, JSON schemas, pgvector, AWS Lambda, Python/TypeScript, SQL/PostgreSQL. One sentence.\n\nRejected resume lacks: production LLM APIs, structured outputs, eval/monitoring, RAG/pgvector maybe only side project mentions but not role focus. It is full-stack/frontend, no LLM production. Could mention though projects pgvector and AWS Lambda, but role''s main LLM pipelines missing. One line.\n\nFinal JSON only.","reasoningChars":1107,"raw":"{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"This resume uniquely shows production LLM API work with JSON-schema-validated structured outputs, evaluation sets and tracing, plus Python/TypeScript, PostgreSQL, pgvector retrieval, and AWS Lambda, directly matching the AI Engineer advert’s core LLM extraction pipeline, evaluation/monitoring, SQL/PostgreSQL, and nice-to-have RAG/Lambda requirements.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"It is a full-stack/frontend resume and does not show production LLM APIs, structured outputs, evaluation sets, or tracing, which are the advert’s main AI engineering requirements.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_AI_Engineer.pdf","reason":"This resume uniquely shows production LLM API work with JSON-schema-validated structured outputs, evaluation sets and tracing, plus Python/TypeScript, PostgreSQL, pgvector retrieval, and AWS Lambda, directly matching the AI Engineer advert’s core LLM extraction pipeline, evaluation/monitoring, SQL/PostgreSQL, and nice-to-have RAG/Lambda requirements.","rejected":[{"sFileName":"Alex_Rivera_CV_Full_Stack.pdf","sReason":"It is a full-stack/frontend resume and does not show production LLM APIs, structured outputs, evaluation sets, or tracing, which are the advert’s main AI engineering requirements."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('ac7338a8-0d11-4b00-b48f-9f910f253adc', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462569 seconds'), 5980, 2905, 1, '[]', '{"model":"deepseek-flash","apiMs":5979,"finishReason":"stop","reasoning":"Let me write the JSON.\n\nWord count limit: 300 total across both sections.\n\naIntroduction: two paragraphs. First: background from standing highlights — working principle, move into tech, degree, current role. Two or three sentences, keep voice.\n\nSecond: why this role, name role and company, what draws them. Mention specific company fact: Fabrikam builds document-processing software for New Zealand councils and utilities.\n\nsWhyGoodFit: three or four sentences of prose. Pick three things advert asks for most clearly: production experience with LLM APIs and structured outputs; strong Python; evaluation and monitoring of ML or LLM systems. Also SQL/PostgreSQL, 3+ years.\n\nLet me draft.\n\nParagraph 1: \"I build software that shows its working, so people can trust what it decides. I came to tech from hospitality, where I ran a café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and I have spent the last two years at Humongous Insurance shipping language model features in production.\"\n\nThat''s 3 sentences. Good.\n\nParagraph 2: \"I am applying for the AI Engineer role at Fabrikam. Turning unstructured documents into checked, structured data is the work I already do, and doing it for councils and utilities, where the details matter, is what draws me to it.\"\n\nHmm \"what draws me to it\" fine. Avoid \"excited\".\n\nsWhyGoodFit:\nRequirement 1: production experience with LLM APIs and structured outputs. Evidence: claims-intake assistant, LLM reads emails and PDFs, output validated against JSON schemas, 2,000 claims a month.\nRequirement 2: Evaluation and monitoring: 300-claim evaluation set and tracing, cut misrouted claims 9% to 3%.\nRequirement 3: Strong Python: Python tooling reconciles supplier invoices; also Python listed. Resume Python: tooling at Margie''s Travel. Also retrieval side project with pgvector (nice to have).\n\nMaybe also SQL and PostgreSQL: booking and itinerary features in PostgreSQL. Hmm, four sentences allowed. Let me do three sentences plus one closing maybe. Keep word count.\n\nDraft:\n\n\"The role needs production experience with LLM APIs and structured outputs, which I have from building a claims-intake assistant where a model reads customer emails and PDFs and its output is validated against JSON schemas before over 2,000 claims a month are routed. Evaluation is the other half of that work: I built a 300-claim evaluation set and step-by-step tracing, which cut misrouted claims from 9% to 3%. My Python is strong and I use it for practical tooling, such as reconciling supplier invoices against bookings, and I have worked with PostgreSQL for several years. I have also built retrieval over 5,000 recipes with pgvector, which matches the retrieval work you mention.\"\n\nThat''s four sentences. Word count check.\n\nLet''s count total.\n\nParagraph 1: \n\"I build software that shows its working, so people can trust what it decides.\" (14)\n\"I came to tech from hospitality, where I ran a café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science.\" (~28)\n\"I finished my degree in 2020 and I have spent the last two years at Humongous Insurance shipping language model features in production.\" (~23)\nTotal ~65.\n\nParagraph 2:\n\"I am applying for the AI Engineer role at Fabrikam.\" (10)\n\"Turning unstructured documents into checked, structured data is the work I already do, and doing it for councils and utilities, where the details matter, is what draws me to it.\" (~32)\nTotal ~42.\n\nIntro total ~107.\n\nsWhyGoodFit:\nSent 1: \"The role needs production experience with LLM APIs and structured outputs, which I have from building a claims-intake assistant where a model reads customer emails and PDFs and its output is validated against JSON schemas before over 2,000 claims a month are routed.\" (~45)\nSent 2: \"Evaluation is the other half of that work: I built a 300-claim evaluation set and step-by-step tracing, which cut misrouted claims from 9% to 3%.\" (~25)\nSent 3: \"My Python is strong, and I use it for practical tooling such as reconciling supplier invoices against bookings, alongside several years of PostgreSQL.\" (~22)\nSent 4: \"I have also built retrieval over 5,000 recipes with pgvector, which matches the retrieval work you mention.\" (~17)\nTotal ~109... wait sent1 45 + 25 + 22 + 17 = 109.\n\nTotal ~216. Under 300. Good.\n\nActually maybe shorten slightly but fine. Let''s make sure no em dashes, no bullet characters. Fine.\n\nNew Zealand English: \"café\", \"behaviour\" not used. \"modelling\" not used. Fine.\n\nCheck banned phrases: none.\n\n\"sWhyGoodFit\" as a string with prose. Good.\n\nMaybe sentence 3 combining Python and PostgreSQL is slightly a duty list but it names requirements. Fine.\n\nLet me refine paragraph 1 to keep voice and 2-3 sentences. Good.\n\nReturn JSON.","reasoningChars":4843,"resume":"Alex_Rivera_CV_AI_Engineer.pdf","introParagraphs":2,"words":212,"wordLimit":300,"raw":"{\"aIntroduction\":[\"I build software that shows its working, so people can trust what it decides. I came to tech from hospitality, where I ran a cafe''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have spent the last two years at Humongous Insurance shipping language model features in production.\",\"I am applying for the AI Engineer role at Fabrikam. Turning unstructured documents into checked, structured data is the work I already do, and doing it for councils and utilities, where the details matter, is what draws me to it.\"],\"sWhyGoodFit\":\"The role needs production experience with LLM APIs and structured outputs, which I have from building a claims-intake assistant where a model reads customer emails and PDFs and its output is validated against JSON schemas before over 2,000 claims a month are routed. Evaluation is the other half of that work: I built a 300-claim evaluation set and step-by-step tracing, which cut misrouted claims from 9% to 3%. My Python is strong, and I use it for practical tooling such as reconciling supplier invoices against bookings, alongside several years of PostgreSQL. I have also built retrieval over 5,000 recipes with pgvector, which matches the retrieval work you mention.\"}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('ac7338a8-0d11-4b00-b48f-9f910f253adc', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4462563 seconds'), 28, 0, 1, '[{"tool":"build_pdf","durationMs":27,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I build software that shows its working, so people can trust what it decides. I came to tech from hospitality, where I ran a cafe''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have spent the last two years at Humongous Insurance shipping language model features in production.","I am applying for the AI Engineer role at Fabrikam. Turning unstructured documents into checked, structured data is the work I already do, and doing it for councils and utilities, where the details matter, is what draws me to it."]},{"heading":"Why I Am a Good Fit","paragraphs":["The role needs production experience with LLM APIs and structured outputs, which I have from building a claims-intake assistant where a model reads customer emails and PDFs and its output is validated against JSON schemas before over 2,000 claims a month are routed. Evaluation is the other half of that work: I built a 300-claim evaluation set and step-by-step tracing, which cut misrouted claims fr… (671 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"AI Engineer, Fabrikam"}}}]', '{"pages":1,"sizeBytes":2712,"words":252}');
