INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('bba3fc66-3c9b-4b61-8301-f495a05a4a8b', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-747380 seconds'), 832, 503, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes a Data and AI Engineer role with responsibilities, requirements, employer, and location.","sLooksLike":null,"model":"deepseek-flash","apiMs":832,"finishReason":"stop","reasoning":"We need answer JSON only per schema. Need decide if job ad. It clearly is job advertisement. Need output {\"bIsJobPost\": true, \"sReason\": \"...\", \"sLooksLike\": null}. Ensure valid JSON.","reasoningChars":183,"inputChars":921,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\": true, \"sReason\": \"It describes a Data and AI Engineer role with responsibilities, requirements, employer, and location.\", \"sLooksLike\": null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('bba3fc66-3c9b-4b61-8301-f495a05a4a8b', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-747380 seconds'), 3882, 1566, 1, '[]', '{"model":"deepseek-flash","apiMs":3882,"finishReason":"stop","reasoning":"We need answer JSON only. Need parse. Need determine sCompany employer Trey Research. bAgency false. sCompanyMeta: industry? public-policy surveys/research? Could be Research? Business: runs public-policy surveys and research for NZ government agencies. website_url null (not provided). sJobTitle \"Data and AI Engineer\". sJobRequirement copy requirements as \"- \" bullet lines. From advert \"You have\" section:\n- 2+ years in data engineering or software engineering\n- Strong Python and SQL\n- Experience with LLM APIs or NLP\n- Clear communication with non-technical researchers\nCould also include responsibilities? The field says requirements, probably \"You have\" only. Maybe copy exactly. sContractType: Fixed-term. sLocation: Wellington (office, flexible hours) -> \"Wellington\" maybe as specific. sJobSummary under 80 words plain. sSource: not stated? Advert not say SEEK etc. Source likely Other? But schema requires SEEK | LinkedIn | Company Website | Trade Me Jobs | Other. Since no URL/source in text, use Other. sSourceUrl null. sTechStack: Python, SQL, dbt, LLM APIs, NLP. dbt is a plus, named tech. LLM APIs maybe named? Also \"data pipelines\"? no. We can include Python, SQL, dbt, LLM APIs, NLP. Maybe \"LLM APIs\" as technology. Need valid JSON. Ensure bAgency boolean true/false not string. The required shape says boolean but examples string? We use false.\n\nsJobRequirement should be string with bullet lines. Use \\n. Keep advert wording. Could include \"- 2+ years in data engineering or software engineering\\n- Strong Python and SQL\\n- Experience with LLM APIs or NLP\\n- Clear communication with non-technical researchers\". Good.\n\nsJobSummary: \"Build data pipelines and LLM components for a research assistant that summarises large volumes of open-text survey answers and links findings to supporting answers. Work with researchers on evaluation sets and accuracy, handle sensitive data, and document pipelines. Fixed-term role in Wellington.\" Under 80 words. Count ~42.\n\nsLocation: \"Wellington\" or \"Wellington office, flexible hours\". \"as specific as advert allows\", maybe \"Wellington\". The advert says Wellington office. Use \"Wellington\". Could use \"Wellington (office, flexible hours)\"? But location field maybe just location. Since advert allows Wellington. Use \"Wellington\". It doesn''t state remote. Fine.\n\nsCompanyMeta industry: \"Research\" or \"Public policy research\". business sentence. website_url null.\n\nNeed only JSON no markdown. Ensure all keys. final.","reasoningChars":2472,"attempt":1,"promptChars":3223,"responseChars":903,"raw":"{\"sCompany\":\"Trey Research\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Public policy research\",\"business\":\"Runs public-policy surveys and research for New Zealand government agencies.\",\"website_url\":null},\"sJobTitle\":\"Data and AI Engineer\",\"sJobRequirement\":\"- 2+ years in data engineering or software engineering\\n- Strong Python and SQL\\n- Experience with LLM APIs or NLP\\n- Clear communication with non-technical researchers\",\"sContractType\":\"Fixed-term\",\"sLocation\":\"Wellington\",\"sJobSummary\":\"Build data pipelines and LLM components for a research assistant that summarises thousands of open-text survey answers and links findings back to supporting answers. Work with researchers on evaluation sets and accuracy, handle sensitive data carefully, and document every pipeline. Fixed-term role in Wellington.\",\"sSource\":\"Other\",\"sSourceUrl\":null,\"sTechStack\":[\"Python\",\"SQL\",\"dbt\",\"LLM APIs\",\"NLP\"]}"}');
