INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('bba3fc66-3c9b-4b61-8301-f495a05a4a8b', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-747376 seconds'), 14, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('bba3fc66-3c9b-4b61-8301-f495a05a4a8b', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-747376 seconds'), 4060, 1894, 1, '[]', '{"model":"deepseek-flash","apiMs":4060,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume. We have two resumes same person, one AI/LLM, one full-stack. Job Data and AI Engineer at Trey Research: build data pipelines and LLM components for research assistant summarises open-text survey answers and links findings. Requirements: 2+ years data/software eng, strong Python SQL, LLM APIs/NLP, communication non-tech researchers. Technologies Python SQL dbt LLM APIs NLP.\n\nResume1 AI/LLM: 4 yrs TypeScript/Python, last two shipping LLM production, messy business text to structured, evaluation sets, tracing. Experience: claims-intake assistant LLM reads emails/PDFs, validate schemas, 2000 claims/month. Built 300-claim eval set tracing cut misroutes. Moved Node services to Lambda. Mentor. Junior full stack: Python tooling reconcile invoices, SQL/Postgres, React Next. Skills includes Python SQL, LLM APIs, NLP? It says AI: LLM APIs, tool calling, structured outputs, JSON Schema/Zod, retrieval, eval sets, tracing. No explicit NLP/dbt. Data pipelines? Not explicit but data engineering adjacent. Strong Python/SQL. LLM APIs. Communication? mentor, finance team.\n\nResume2 Full-stack: full stack React Next Node, TypeScript, accessible, typed APIs, tests. Python in skills but no LLM APIs, no eval sets, no data pipelines, no NLP. LLM side project with retrieval but less central. Poor fit.\n\nNeed return JSON with sFileName exact, sReason comparative: Resume1 shows production LLM APIs, structured outputs, evaluation sets/tracing for validating model outputs on messy text, matching LLM components/evaluation sets in advert, plus Python/SQL; Resume2 lacks LLM API and NLP experience. aRejected with one line.\n\nNeed ensure valid JSON. The file names: \"Alex_Rivera_CV_AI_Engineer.pdf\" and \"Alex_Rivera_CV_Full_Stack.pdf\". sFileName best: Alex_Rivera_CV_AI_Engineer.pdf.\n\nNeed one-line reason for rejected: Full-stack/frontend focus, lacks LLM APIs/NLP and data pipeline work. Maybe mention no dbt? Not required but tech. Could say \"It emphasizes React/Next.js full-stack work and does not show LLM API/NLP production experience or evaluation sets required for the research assistant.\"\n\nNeed no extra. Must adhere schema. final JSON.","reasoningChars":2186,"raw":"{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"This resume uniquely shows production LLM API work, structured output validation, evaluation sets, and tracing for turning messy text into checked data, directly matching the advert''s LLM components and accuracy/evaluation requirements, while also listing Python and SQL.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"It is aimed at full-stack/frontend React and Node roles and lacks the advert''s required LLM API, NLP, evaluation-set, and data-pipeline experience.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_AI_Engineer.pdf","reason":"This resume uniquely shows production LLM API work, structured output validation, evaluation sets, and tracing for turning messy text into checked data, directly matching the advert''s LLM components and accuracy/evaluation requirements, while also listing Python and SQL.","rejected":[{"sFileName":"Alex_Rivera_CV_Full_Stack.pdf","sReason":"It is aimed at full-stack/frontend React and Node roles and lacks the advert''s required LLM API, NLP, evaluation-set, and data-pipeline experience."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('bba3fc66-3c9b-4b61-8301-f495a05a4a8b', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-747372 seconds'), 10702, 3902, 1, '[]', '{"model":"deepseek-flash","apiMs":10700,"finishReason":"stop","reasoning":"Let me draft.\n\nRequirements: 2+ years data/software engineering; strong Python and SQL; LLM APIs or NLP; clear communication with non-technical researchers.\n\nIntro paragraph 1: background from standing highlights: working principle, move into tech, degree, current role. Two or three sentences, their voice.\n\nParagraph 2: why this role, name role and company, say what draws them. Company fact: runs public-policy surveys and research for NZ government agencies. Something specific: summarising thousands of open-text survey answers, linking findings back to supporting answers.\n\nFit section: 3-4 sentences. Each names requirement + evidence.\n\n1. \"The role asks for two or more years in software or data engineering; I have four, the last two spent shipping LLM features to production at Humongous Insurance.\" Wait, two years as LLM, four total. OK.\n\n2. Python and SQL: built Python tooling that reconciles supplier invoices against bookings; SQL in PostgreSQL work — booking and itinerary features in React, Next.js and PostgreSQL. Hmm, evidence for SQL: PostgreSQL. Say \"strong Python and SQL\" - Python tooling at Margie''s Travel, SQL via PostgreSQL across booking features and the evaluation work.\n\n3. LLM APIs or NLP: claims-intake assistant with LLM reading emails and PDFs, validated against JSON schemas.\n\n4. Clear communication with non-technical researchers: mentor two graduate developers; worked with finance team. Hmm, mentor grads is technical-ish. The finance team tooling was for the finance team (non-technical). Say: \"explaining model behaviour to people who do not build models\" — I trained grads and built tracing... Careful not to invent. The tracing and evaluation sets made model behaviour visible so teams can trust it. And the finance tooling saved the finance team a day a month. I''ll write: \"Talking about models with people who do not build them is the part I enjoy most, and it is how the invoice tooling and the tracing work at Humongous were shaped, sitting with the finance team and the claims staff to see what they needed to check.\" Hmm, invented detail about sitting with them. Keep safe: \"I built the tracing and evaluation work so claims staff could see why a claim was routed the way it was, and I mentor two graduates.\"\n\nWord count: 300 total max. Let''s aim ~260-280.\n\nDraft intro para 1: \"I come to software from hospitality. I ran a busy café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have spent four years as a software engineer, the last two shipping language model features in production, and I am now at Humongous Insurance. My working principle is simple: make the software show its working, so people can trust what it decides.\"\n\nThat''s maybe a bit long, 5 sentences. Trim: keep two-three sentences for para 1. The guidance says keep to two or three sentences. Hmm, but it says draw on working principle, move into tech, degree, current role. Let me do 4 sentences compact.\n\n\"I came to software from hospitality: I ran a busy café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have been a software engineer for four years, the last two shipping language model features in production, and I am now at Humongous Insurance in Auckland. My working principle is to make the software show its working, so people can trust what it decides.\"\n\nThree sentences. Good.\n\nPara 2: \"I am applying for the Data and AI Engineer role at Trey Research. What draws me is the research assistant itself: turning thousands of open-text survey answers into summaries that link back to the answers behind them, and doing evaluation work with the researchers who will use it. Getting that right for public-policy work, where the findings have to hold up to scrutiny, is the kind of problem I want to spend my days on.\"\n\nHmm \"I am applying for\" — avoid \"excited to apply\" only. Fine.\n\nFit: 4 sentences.\n\n\"The role asks for two or more years in data or software engineering, and I have four, the last two spent shipping language model features to production rather than prototypes. On the Python and SQL side, I wrote Python tooling that reconciles supplier invoices against bookings, saving the finance team a day a month, and I have built booking and itinerary features on PostgreSQL. For LLM work, I built a claims-intake assistant that reads customer emails and PDFs, validates the output against JSON schemas and routes over 2,000 claims a month, with a 300-claim evaluation set and step-by-step tracing that cut misrouted claims from 9% to 3%. And because the findings have to make sense to the people who asked for them, I keep the model''s reasoning visible and mentor two graduates.\"\n\nHmm the last sentence should answer \"clear communication with non-technical researchers\". \"I keep the model''s reasoning visible\" — for researchers. Let me rewrite: \"The work also has to make sense to people who did not build it, which is why I built step-by-step tracing so claims staff could see why a claim was routed as it was, and I mentor two graduates.\"\n\nBut tracing already mentioned. Restructure so tracing goes in the communication sentence.\n\nSentence 3: LLM: claims-intake assistant + evaluation set that cut misrouted claims 9% to 3%.\nSentence 4: communication: tracing so claims staff could see why..., and mentoring two graduates.\n\nLet me count words.\n\nIntro p1: \n\"I came to software from hospitality: I ran a busy café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have been a software engineer for four years, the last two shipping language model features in production, and I am now at Humongous Insurance in Auckland. My working principle is to make the software show its working, so people can trust what it decides.\"\nCount: sentence1: I(1) came2 to3 software4 from5 hospit…","reasoningChars":8880,"resume":"Alex_Rivera_CV_AI_Engineer.pdf","introParagraphs":2,"words":284,"wordLimit":300,"raw":"{\"aIntroduction\": [\"I came to software from hospitality: I ran a busy café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have been a software engineer for four years, the last two shipping language model features in production, and I am now at Humongous Insurance in Auckland. My working principle is to make the software show its working, so people can trust what it decides.\", \"I am applying for the Data and AI Engineer role at Trey Research. Trey Research runs public-policy surveys for New Zealand government agencies, and what draws me to this role is the assistant that summarises thousands of open-text survey answers and links each finding back to the answers behind it. Building that with the researchers, and making it accurate enough to stand behind, is the work I want to do.\"], \"sWhyGoodFit\": \"The role asks for two or more years in software or data engineering, and I have four, with the last two spent shipping language model features to production rather than prototypes. It also asks for strong Python and SQL: I wrote Python tooling that reconciles supplier invoices against bookings for the finance team, and built booking and itinerary features on PostgreSQL. My language model work is the closest match, a claims-intake assistant that reads customer emails and PDFs, checks the output against JSON schemas and routes over 2,000 claims a month, backed by a 300-claim evaluation set that cut misrouted claims from 9% to 3%. Because researchers have to be able to trust what the model says, I built step-by-step tracing so claims staff could see why a claim was routed the way it was.\"}"}');
