INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252980 seconds'), 1253, 491, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an open Software Engineer role with responsibilities, requirements, and application details.","sLooksLike":null,"model":"deepseek-flash","apiMs":1253,"finishReason":"stop","reasoning":"We need answer JSON only. Need decide if job advertisement. This is clearly job ad. Need return schema. bIsJobPost true, sReason short, sLooksLike null. Need ensure valid JSON.","reasoningChars":176,"inputChars":824,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\":true,\"sReason\":\"It describes an open Software Engineer role with responsibilities, requirements, and application details.\",\"sLooksLike\":null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252979 seconds'), 3030, 1441, 1, '[]', '{"model":"deepseek-flash","apiMs":3030,"finishReason":"stop","reasoning":"Let me extract.\n\nsCompany: Woodgrove Bank\nbAgency: false\nsCompanyMeta: industry: Banking; business: \"A New Zealand-owned bank serving 300,000 customers.\"; website_url: null (not stated)\nsJobTitle: \"Software Engineer, Platform\"\nsJobRequirement: bullets from \"About you\" section.\nsContractType: Permanent\nsLocation: \"Auckland CBD\" (or \"Auckland CBD (hybrid)\")\nsJobSummary: under 80 words.\nsSource: not stated in text — is there a URL? No. sSource required \"SEEK | LinkedIn | Company Website | Trade Me Jobs | Other\". Not stated. Hmm, the rules say return null when advert doesn''t state something. But schema says sSource enum. Which one? The advert appears from company... Actually source unknown. I''ll use \"Other\"? Hmm. There''s no indication. The rules say null when not stated, but schema doesn''t allow null. I''ll pick \"Other\".\n\nActually, given the format looks like a job board listing with \"·\" separators... could be SEEK or Trade Me. Not determinable. Use \"Other\".\n\nsSourceUrl: null.\n\nsTechStack: C#, .NET, Azure, Terraform, Bicep, Java? Java is mentioned as alternative. Named technologies — Java qualifies. I''ll include Java. Hmm, arguably. It''s a named technology. Include.\n\nRequirements copy:\n- 3+ years in software engineering, ideally on platform or backend services\n- C# and .NET (or Java and willingness to learn .NET)\n- Azure or another major cloud\n- Infrastructure as code (Terraform or Bicep)\n- Comfortable on an on-call roster","reasoningChars":1441,"attempt":1,"promptChars":3126,"responseChars":1078,"raw":"{\"sCompany\":\"Woodgrove Bank\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Banking\",\"business\":\"Woodgrove Bank is a New Zealand-owned bank serving 300,000 customers.\",\"website_url\":null},\"sJobTitle\":\"Software Engineer, Platform\",\"sJobRequirement\":\"- 3+ years in software engineering, ideally on platform or backend services\\n- C# and .NET (or Java and willingness to learn .NET)\\n- Azure or another major cloud\\n- Infrastructure as code (Terraform or Bicep)\\n- Comfortable on an on-call roster\",\"sContractType\":\"Permanent\",\"sLocation\":\"Auckland CBD (hybrid)\",\"sJobSummary\":\"Woodgrove Bank''s Platform team builds shared services such as identity, payments, notifications and observability. The engineer builds and runs internal platform services in C# and .NET on Azure, improves deployment pipelines and developer tooling, owns reliability through monitoring, alerting and incident reviews, and works with security on safe-by-default patterns. The role includes an on-call roster.\",\"sSource\":\"Other\",\"sSourceUrl\":null,\"sTechStack\":[\"C#\",\".NET\",\"Azure\",\"Java\",\"Terraform\",\"Bicep\"]}"}');
