INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252976 seconds'), 29, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252976 seconds'), 8336, 2959, 1, '[]', '{"model":"deepseek-flash","apiMs":8336,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume for job. We have two resumes same person tailored. Job: Software Engineer, Platform at Woodgrove Bank. Requirements: 3+ years software engineering ideally platform/backend, C#/.NET or Java willingness learn .NET, Azure or major cloud, IaC Terraform/Bicep, on-call. Technologies C#, .NET, Azure, Java, Terraform, Bicep.\n\nResumes:\n1 AI Engineer: TypeScript/Python, LLM, AWS Lambda, Node.js, GitHub Actions. No C#/.NET, no Azure (AWS), no Terraform/Bicep, no on-call, platform? Not really. Maybe backend services? Minimal.\n2 Full Stack: React/Next.js/Node, AWS Lambda, no C#/.NET, no Azure, no IaC, no on-call. Also not platform. Which is better? Neither has .NET/Azure/Terraform. But job says C# .NET or Java willingness learn. Neither has Java. Need choose best fit. We must judge overlap. Resume 1 mentions \"Moved four Node.js services to AWS Lambda with GitHub Actions deployments\" but resume 2 same. Resume 2 is full-stack/frontend. Resume 1 has AI/LLM, backend data processing, JSON schemas, tracing, evaluation, perhaps platform-ish observability? But no .NET. Job platform shared services identity payments notifications observability. Resume 1 has \"model behaviour visible with tracing and evaluation sets\" maybe observability, and backend data. Resume 2 has frontend heavy. For platform role, backend services and cloud more relevant than frontend. Resume 1 has backend? It has Node.js services, AWS Lambda, Python tooling, PostgreSQL, LLM. Resume 2 has typed REST APIs Node.js PostgreSQL, backend. But also frontend. Resume 1''s \"AI/LLM applications\" is different role. Resume 2''s full-stack/frontend is different role. Which is closer to platform? Neither. Resume 2 has Node.js/PostgreSQL REST APIs and cloud, testing. Resume 1 has AWS Lambda, Node services, Python, tracing/evaluation, but AI focus. The job is platform/backend services. Resume 2 explicitly backend: \"Designed typed REST APIs in Node.js and PostgreSQL for portal and partner integrations\" and \"Moved four Node.js services to AWS Lambda with GitHub Actions deployments.\" Resume 1 also has \"Moved four Node.js services to AWS Lambda...\" but focuses AI. However platform role includes internal platform services, deployment pipelines, developer tooling, reliability through monitoring, alerting. Resume 1: \"step-by-step tracing\", evaluation sets, \"make model behaviour visible\" maybe observability. Resume 2: accessibility, frontend performance. For platform, backend/API/cloud/deployments matter more. Resume 2 has backend/API and AWS Lambda. But both lack .NET/Azure/IaC/on-call. We need choose which best fits. The prompt: \"A resume aimed at a different kind of role is a poor fit even if it is longer or more impressive.\" Resume 1 aimed AI engineer. Resume 2 aimed full-stack/frontend. Neither platform. But maybe full-stack with backend services is closer to platform than AI/LLM? Platform role is backend services, cloud, reliability. Resume 2 has backend APIs and cloud deployments, but frontend. Resume 1 has LLM/AI, not platform. However resume 1 has backend data and observability/tracing. Hmm.\n\nCould there be hidden expectation? We pick best among candidate resumes. The job requirements: C# .NET or Java willingness to learn .NET. Neither. Azure or major cloud: both AWS. IaC: none. On-call: none. 3+ years: both 4. Platform/backend: resume 2 has backend APIs; resume 1 has Node services and AI, but \"Software Engineer, AI and LLM applications\" not platform/backend. Resume 2 title \"Full Stack Software Engineer\" includes backend. Resume 2 is more general software engineer, and backend APIs. Resume 1 is specialized AI. The platform role likely wants general backend/platform, so full-stack/backend is closer. But platform team builds shared services such as identity, payments, notifications, observability. Full-stack resume has \"Designed typed REST APIs in Node.js and PostgreSQL for portal and two partner integrations.\" That''s service/API work. AI resume has \"Built a claims-intake assistant\" not shared platform. So resume 2 better fit. But need mention what it has others do not: backend REST API design in Node.js/PostgreSQL and cloud deployment via AWS Lambda/GitHub Actions, closest to platform backend services and cloud deployment pipelines. It lacks .NET/Azure/Terraform but so does other. Need reject resume 1 with reason: focused on LLM/AI applications, not platform/backend services; lacks .NET/Azure/IaC and on-call.\n\nBut wait, the job says \"C# and .NET (or Java and willingness to learn .NET)\". Neither has Java. Maybe resume 2''s \"typed REST APIs\" and full-stack could be transferable. Resume 1 has TypeScript/Python, not Java. Resume 2 also TypeScript/Python. No difference. Could there be any mention of \"Java\"? No. So we can''t satisfy.\n\nNeed JSON only. sFileName exact as given: Alex_Rivera_CV_Full_Stack.pdf. sReason one sentence: \"This resume shows backend REST API/service design in Node.js and PostgreSQL plus cloud deployment (AWS Lambda, GitHub Actions), which aligns more closely with the platform team''s backend shared services and deployment pipeline work than the AI-focused resume, though both lack the advert''s C#/.NET, Azure, Terraform/Bicep and on-call specifics.\"\n\nBut sReason should say what this resume has that others do not, naming advert requirement it answers. It should be comparative, not \"fits well\". The rejected reason one line.\n\nNeed ensure JSON valid. Use exactly fields. aRejected array with one object. File name exact: Alex_Rivera_CV_AI_Engineer.pdf. sReason: \"Unlike the AI/LLM-focused resume, this resume shows direct backend service/API development (typed Node.js REST APIs on PostgreSQL) and cloud deployment experience (AWS Lambda with GitHub Actions), which better matches the platform team''s backend shared-services and deployment-pipeline needs, even though it still does not cover C#/.NET, Azure, Terraform/Bicep or on-call.\"\n\nRejected: \"Focused on AI/LLM applications and evaluation/tracing; lacks platf…","reasoningChars":6365,"raw":"{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"Unlike the AI/LLM-focused resume, this resume shows direct backend service/API development (typed Node.js REST APIs on PostgreSQL) and cloud deployment experience (AWS Lambda with GitHub Actions), which better matches the platform team''s backend shared-services and deployment-pipeline needs, even though it still does not cover C#/.NET, Azure, Terraform/Bicep or on-call.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"Focused on AI/LLM applications and evaluation/tracing; lacks platform/backend service design and the advert''s C#/.NET, Azure, Terraform/Bicep and on-call requirements.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_Full_Stack.pdf","reason":"Unlike the AI/LLM-focused resume, this resume shows direct backend service/API development (typed Node.js REST APIs on PostgreSQL) and cloud deployment experience (AWS Lambda with GitHub Actions), which better matches the platform team''s backend shared-services and deployment-pipeline needs, even though it still does not cover C#/.NET, Azure, Terraform/Bicep or on-call.","rejected":[{"sFileName":"Alex_Rivera_CV_AI_Engineer.pdf","sReason":"Focused on AI/LLM applications and evaluation/tracing; lacks platform/backend service design and the advert''s C#/.NET, Azure, Terraform/Bicep and on-call requirements."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252968 seconds'), 8460, 3300, 1, '[]', '{"model":"deepseek-flash","apiMs":8460,"finishReason":"stop","reasoning":"Let me write.\n\nIntro para 1: background from standing highlights: working principle, move into tech, degree, current role. Two or three sentences, their voice.\n\nPara 2: why this role, name role and company, what draws them, mention specific company fact: NZ-owned bank serving 300,000 customers.\n\nWhy good fit: three things advert asks for most clearly: 3+ years backend/platform; C#/.NET or Java and willingness to learn .NET; Azure or another cloud; infrastructure as code; on-call comfort. Pick three: experience (four years building backend services), cloud/AWS Lambda deployments, and reliability/on-call? Resume shows... on-call not shown. Hmm. Careful: never claim experience the resume does not show. On-call is not in resume. Infrastructure as code not in resume. C#/.NET not in resume — but \"Java and willingness to learn .NET\" — resume doesn''t show Java either. So maybe better to pick: years of experience on backend services; cloud (AWS Lambda, GitHub Actions deployments); tests/regressions... but the third requirement should be one of the advert''s asks. Options: \"works with security on safe-by-default patterns\", \"reliability through monitoring\". Hmm, resume shows typed REST APIs, PostgreSQL, tests.\n\nLet me choose: (1) 3+ years in software engineering on backend services — four years, typed REST APIs in Node.js and PostgreSQL. (2) Azure or another major cloud — moved four Node.js services to AWS Lambda with GitHub Actions deployments. (3) Willingness to learn .NET — hmm, careful not to over-claim. Could say \"The role accepts Java and a willingness to learn .NET; my background is Node.js and Python, and I taught myself Python to automate a stock count before I studied computer science, so picking up C# and .NET on the job is a step I have taken before.\" That''s honest, drawn from standing highlights. But the advert asks for \"C# and .NET (or Java and willingness to learn .NET)\" — candidate doesn''t have Java. Saying \"willingness to learn .NET\" isn''t claiming experience. That''s fine.\n\nOr third: tests/reliability — \"owns reliability through monitoring, alerting and incident reviews\" — resume: added Vitest and Playwright tests catching regressions. That maps to reliability but is not monitoring. Hmm, could frame: \"The role owns reliability... I added Vitest and Playwright tests to a codebase that had none, catching release regressions before customers did.\" That''s a reasonable link to reliability.\n\nMaybe pick three: (1) 3+ years backend/platform; (2) cloud; (3) reliability/tests. Then closing sentence on learning .NET? Closing sentence only if adds something. Maybe close with the working principle or the .NET willingness.\n\nWord count ~300 total. Let''s aim ~290.\n\nWrite para 1 (~55 words), para 2 (~60 words), why fit 4 sentences (~140 words).\n\nDraft intro 1:\n\"I build software that shows its working, so the people using it can trust what it decides. I came to this from hospitality, where I ran a busy café''s ordering system, taught myself Python to automate the stock count, and then went back to study computer science. I finished my degree in 2020 and have spent four years as a software engineer, the last two at Humongous Insurance in Auckland shipping language model features in production.\"\n\nPara 2:\n\"I am applying for the Software Engineer, Platform role at Woodgrove Bank. Shared services like identity, payments and notifications are the kind of work I want to do more of, and Woodgrove being a New Zealand-owned bank serving 300,000 customers makes that concrete for me.\"\n\nWhy good fit:\n\"The role wants three or more years on backend or platform services, and I have four years of it, most recently designing typed REST APIs in Node.js and PostgreSQL for a claims portal and two partner integrations. It also asks for hands-on work with a major cloud; I moved four Node.js services to AWS Lambda and set up the GitHub Actions deployments that ship them. Reliability is part of the job too, and I have built the safety net for that before, adding Vitest and Playwright tests to a React and Next.js codebase that had none so regressions were caught before customers saw them. My day-to-day languages are TypeScript, Node.js and Python rather than C# or Java, so .NET would be new to me, but I taught myself Python to fix a stock count once and I am happy to do that again.\"\n\nHmm, the last sentence — is it fine? It mentions no Java. The advert says \"C# and .NET (or Java and willingness to learn .NET)\". Claiming Java not present — avoid saying \"rather than C# or Java\"? That''s fine, honest. But maybe better not to highlight gaps too heavily. Actually honesty is good. But the instruction: three sentences one per requirement, close with one sentence only if adds. This adds the .NET willingness. Fine.\n\nWord count check.\n\nPara1: I(1) build2 software3 that4 shows5 its6 working7, so8 the9 people10 using11 it12 can13 trust14 what15 it16 decides17. I18 came19 to20 this21 from22 hospitality23, where24 I25 ran26 a27 busy28 café''s29 ordering30 system31, taught32 myself33 Python34 to35 automate36 the37 stock38 count39, and40 then41 went42 back43 to44 study45 computer46 science47. I48 finished49 my50 degree51 in52 2020(53) and54 have55 spent56 four57 years58 as59 a60 software61 engineer62, the63 last64 two65 at66 Humongous67 Insurance68 in69 Auckland70 shipping71 language72 model73 features74 in75 production76. ~76 words. A bit long but fine.\n\nPara2: I1 am2 applying3 for4 the5 Software6 Engineer7, Platform8 role9 at10 Woodgrove11 Bank12. Shared13 services14 like15 identity16, payments17 and18 notifications19 are20 the21 kind22 of23 work24 I25 want26 to27 do28 more29 of30, and31 Woodgrove32 being33 a34 New35 Zealand-owned36 bank37 serving38 300,000(39) customers40 makes41 that42 concrete43 for44 me45. ~45 words.\n\nWhy: sentence1 ~45, sentence2 ~35, sentence3 ~40, sentence4 ~45 = ~165. Total ~286. Good.\n\nTrim slightly. Maybe shorten para 1 a bit.\n\n\"No em dashes\" — check. Use commas. \"New Zealand-owned\" fine. Avoid \"I am excited\". Good.\n…","reasoningChars":6232,"resume":"Alex_Rivera_CV_Full_Stack.pdf","introParagraphs":2,"words":269,"wordLimit":300,"raw":"{\n  \"aIntroduction\": [\n    \"I build software that shows its working, so the people using it can trust what it decides. I came to this from hospitality, where I ran a busy café''s ordering system, taught myself Python to automate the stock count, and then went back to study computer science. I finished my degree in 2020 and have spent four years as a software engineer, the last two at Humongous Insurance in Auckland, shipping language model features in production.\",\n    \"I am applying for the Software Engineer, Platform role at Woodgrove Bank. Shared services like identity, payments and notifications are the kind of work I want to do more of, and Woodgrove being a New Zealand-owned bank serving 300,000 customers makes that concrete for me.\"\n  ],\n  \"sWhyGoodFit\": \"The role asks for three or more years on platform or backend services, and I have four, most recently designing typed REST APIs in Node.js and PostgreSQL for a claims portal and two partner integrations. It also asks for hands-on work with a major cloud, which is what I did when I moved four Node.js services to AWS Lambda and set up the GitHub Actions deployments that ship them. Reliability is part of the job too, and I have built the safety net for it before: I added Vitest and Playwright tests to a React and Next.js codebase that had none, so regressions were caught before customers saw them. My working languages are TypeScript, Node.js and Python rather than C# or Java, so .NET would be new to me, but I taught myself Python to fix a stock count once and I am happy to do that again.\"\n}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('c4105d34-02d5-4797-b4c8-c5fd652c7b8e', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3252959 seconds'), 8, 0, 1, '[{"tool":"build_pdf","durationMs":8,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I build software that shows its working, so the people using it can trust what it decides. I came to this from hospitality, where I ran a busy café''s ordering system, taught myself Python to automate the stock count, and then went back to study computer science. I finished my degree in 2020 and have spent four years as a software engineer, the last two at Humongous Insurance in Auckland, shipping … (438 chars)","I am applying for the Software Engineer, Platform role at Woodgrove Bank. Shared services like identity, payments and notifications are the kind of work I want to do more of, and Woodgrove being a New Zealand-owned bank serving 300,000 customers makes that concrete for me."]},{"heading":"Why I Am a Good Fit","paragraphs":["The role asks for three or more years on platform or backend services, and I have four, most recently designing typed REST APIs in Node.js and PostgreSQL for a claims portal and two partner integrations. It also asks for hands-on work with a major cloud, which is what I did when I moved four Node.js services to AWS Lambda and set up the GitHub Actions deployments that ship them. Reliability is par… (795 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"Software Engineer, Platform, Woodgrove Bank"}}}]', '{"pages":1,"sizeBytes":2933,"words":309}');
