INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043380 seconds'), 967, 478, 1, '[]', '{"bIsJobPost":true,"sReason":"It advertises a Frontend Engineer role at Fourth Coffee, listing responsibilities, required skills, and perks.","sLooksLike":null,"model":"deepseek-flash","apiMs":967,"finishReason":"stop","reasoning":"The text is clearly a job advertisement. Return JSON.\n\nNote: \"bIsJobPost\" true, sReason short sentence, sLooksLike null.","reasoningChars":120,"inputChars":823,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\": true, \"sReason\": \"It advertises a Frontend Engineer role at Fourth Coffee, listing responsibilities, required skills, and perks.\", \"sLooksLike\": null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043379 seconds'), 6671, 2227, 1, '[]', '{"model":"deepseek-flash","apiMs":6670,"finishReason":"stop","reasoning":"We need answer JSON only. Need parse advert.\n\nCompany: Fourth Coffee. bAgency false. sCompanyMeta: industry? Coffee? The advert says roasts and delivers coffee subscriptions. Business one sentence. website_url? Advert mentions careers page but no URL. Null.\n\nJob title: Frontend Engineer.\n\nRequirements copied as \"- \" bullet lines from advert. The \"You have\" section. Could include nice to have? sJobRequirement \"the requirements as ''- '' bullet lines, copied from advert. Keep advert wording.\" We should include required \"You have\" bullets. Maybe also \"Nice to have\"? Requirements can include nice-to-have? We can include as separate bullet maybe \"- Nice to have: Next.js, design tokens, analytics.\" But instructions: copy requirements. The advert has \"You have\" and \"Nice to have\". I''d include You have bullets and maybe nice to have. Keep wording.\n\nContract type: Full time stated? sContractType options Permanent | Fixed-term | Part-time | Contract | Casual | Internship. \"Full time\" maps to Permanent? It says Full time. Since not stated employment type? It says Full time. But allowed values no \"Full-time\". Use Permanent when not say. But it says Full time. Hmm sContractType only these values. Full time is not an option. Permanent is reasonable default. But \"Full time\" means permanent? Could be fixed-term full-time. The rule: when advert does not state employment type, use Permanent. It states \"Full time\" which is not in enum. Could sContractType be Permanent? I think yes.\n\nLocation: Christchurch. Hybrid from Sydenham roastery. Specific? \"Christchurch (hybrid, Sydenham roastery)\"? Advert: \"Fourth Coffee · Christchurch · Full time\" and \"Hybrid from our Sydenham roastery.\" sLocation as specific as advert allows. Could be \"Christchurch (hybrid, Sydenham roastery)\"? The instruction examples \"Auckland (hybrid)\". Use \"Christchurch (hybrid, Sydenham)\". Maybe \"Christchurch · Hybrid from Sydenham roastery\" but location string. I''ll use \"Christchurch (hybrid, Sydenham roastery)\"? That is specific. But maybe just \"Christchurch (hybrid)\". The roastery in Sydenham is a suburb. Advert says hybrid from our Sydenham roastery. So specific: \"Christchurch (hybrid, Sydenham roastery)\".\n\nSummary under 80 words. Plain description. \"Fourth Coffee is hiring a Frontend Engineer for its product team. The role builds the customer subscription app in React and TypeScript, owns the design system and component library, and improves speed and accessibility across devices. It works with design and two backend engineers. Hybrid from the Sydenham roastery in Christchurch.\" Count ~55. Good.\n\nSource: \"Company Website\" because posted on Fourth Coffee careers page. sSourceUrl null (no URL). Or maybe \"Other\"? Source enum: SEEX | LinkedIn | Company Website | Trade Me Jobs | Other. It says \"Posted on the Fourth Coffee careers page\" => Company Website. SourceUrl null since no URL.\n\nTech stack named technologies: React, TypeScript, Vitest, Testing Library, Playwright, Next.js. Also WCAG? Accessibility standard? \"WCAG\" is a standard, not tech? Named technologies only. WCAG maybe not tech. Design tokens? Not a specific tech. Analytics? not named. Could include React, TypeScript, Vitest, Testing Library, Playwright, Next.js. \"component testing\" no. \"design system\" no. \"design tokens\" no. \"analytics\" no. \"WCAG\" maybe inclusive? The rules: named technologies only (languages, frameworks, cloud, tools, test frameworks). WCAG is a guideline, not technology. So not.\n\nCompanyMeta industry: Coffee? e.g. Coffee, E-commerce? Advert says roasts and delivers coffee subscriptions. Industry could be \"Coffee subscriptions\" or \"Food & Beverage\". Use \"Coffee / D2C subscriptions\"? It''s string. \"Coffee\" is safe. Business: \"Fourth Coffee roasts and delivers coffee subscriptions to 40,000 homes and offices across New Zealand.\" That''s exactly advert. website_url null.\n\nNeed JSON only. Ensure no markdown.\n\nCheck sCompany: Fourth Coffee. bAgency false boolean. sCompanyMeta fields.\n\nPotential issue: sJobRequirement should include \"Nice to have\" as requirement? Let''s format:\n\n\"- 2+ years of professional frontend development\n- Strong React and TypeScript\n- Care for accessibility (WCAG) and performance\n- Experience with component testing (Vitest, Testing Library or Playwright)\n- Nice to have: Next.js, design tokens, analytics.\"\n\nCould include \"You have\" heading? No bullet only. Good.\n\nsContractType: \"Permanent\" as per default. Though full time. Could be \"Permanent\" because full time. If we interpret \"Full time\" as contract type? allowed \"Part-time\" but no Full-time. Permanent is best.\n\nsLocation: \"Christchurch (hybrid, Sydenham roastery)\" maybe okay. It says \"Hybrid from our Sydenham roastery.\" I might use \"Christchurch (hybrid from Sydenham roastery)\" but that''s long. Example \"Auckland (hybrid)\". I''ll do \"Christchurch (hybrid, Sydenham)\".\n\nNow output JSON object. Ensure valid JSON. Use null unquoted. Arrays. No trailing commas.\n\nFinal.","reasoningChars":4944,"attempt":1,"promptChars":3125,"responseChars":1082,"raw":"{\"sCompany\":\"Fourth Coffee\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Coffee\",\"business\":\"Fourth Coffee roasts and delivers coffee subscriptions to 40,000 homes and offices across New Zealand.\",\"website_url\":null},\"sJobTitle\":\"Frontend Engineer\",\"sJobRequirement\":\"- 2+ years of professional frontend development\\n- Strong React and TypeScript\\n- Care for accessibility (WCAG) and performance\\n- Experience with component testing (Vitest, Testing Library or Playwright)\\n- Nice to have: Next.js, design tokens, analytics.\",\"sContractType\":\"Permanent\",\"sLocation\":\"Christchurch (hybrid, Sydenham)\",\"sJobSummary\":\"Fourth Coffee is hiring a Frontend Engineer for its product team. The role builds the customer subscription app in React and TypeScript, owns the design system and component library, and improves speed and accessibility across devices. It works with design and two backend engineers. Hybrid from the Sydenham roastery in Christchurch.\",\"sSource\":\"Company Website\",\"sSourceUrl\":null,\"sTechStack\":[\"React\",\"TypeScript\",\"Vitest\",\"Testing Library\",\"Playwright\",\"Next.js\"]}"}');
