INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043373 seconds'), 30, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043373 seconds'), 3072, 1744, 1, '[]', '{"model":"deepseek-flash","apiMs":3071,"finishReason":"stop","reasoning":"We need answer JSON only. Need choose best resume for Frontend Engineer at Fourth Coffee. Compare resume1 AI engineer vs resume2 full-stack/frontend. Need judge overlap real experience: role main tasks React TypeScript, design system/component library, speed/accessibility, component testing Vitest/Testing Library/Playwright, nice Next.js, design tokens, analytics. Resume2 directly frontend/full-stack: React, Next.js, TypeScript, accessible interfaces, WCAG 2.1 AA, performance page load, Vitest Playwright, design systems. Resume1 AI engineering: TypeScript/Python, LLM, some React/Next.js/Vitest/Playwright in junior role, but aimed AI role. So best resume2. Need JSON with sFileName exact \"Alex_Rivera_CV_Full_Stack.pdf\". sReason one sentence comparative naming advert requirement. aRejected include resume1 one line lacks etc. Need ensure JSON valid. The schema says aRejected array of objects. Use exact file names. sReason: \"It shows hands-on React/Next.js/TypeScript product work, WCAG 2.1 AA accessibility, performance improvements, and Vitest/Playwright component testing, directly matching the frontend role; the AI resume is aimed at LLM applications and lacks design-system/component-library ownership.\" Maybe one sentence. For rejected: resume1 lacks professional frontend focus/design system/accessibility etc. Need maybe mention it has some React but not enough. Ensure no markdown, just JSON.","reasoningChars":1411,"raw":"{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"This resume directly shows React/Next.js/TypeScript product work, WCAG 2.1 AA accessibility, performance improvements, and Vitest/Playwright testing, matching the advert’s core frontend requirements and design-system context unlike the AI-focused resume.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"It is aimed at AI/LLM engineering and only mentions React, Next.js, Vitest and Playwright briefly, so it lacks the sustained frontend, accessibility, performance, and component-library ownership evidence this role needs.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_Full_Stack.pdf","reason":"This resume directly shows React/Next.js/TypeScript product work, WCAG 2.1 AA accessibility, performance improvements, and Vitest/Playwright testing, matching the advert’s core frontend requirements and design-system context unlike the AI-focused resume.","rejected":[{"sFileName":"Alex_Rivera_CV_AI_Engineer.pdf","sReason":"It is aimed at AI/LLM engineering and only mentions React, Next.js, Vitest and Playwright briefly, so it lacks the sustained frontend, accessibility, performance, and component-library ownership evidence this role needs."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043370 seconds'), 7013, 2990, 1, '[]', '{"model":"deepseek-flash","apiMs":7012,"finishReason":"stop","reasoning":"Let me write the JSON.\n\nIntro paragraph 1: background from standing highlights: working principle, move into tech, degree, current role. Two or three sentences, keep voice.\n\nParagraph 2: why this role, name role and company, mention specific company fact (roasts and delivers coffee subscriptions to 40,000 homes and offices across NZ).\n\nsWhyGoodFit: three requirements from advert most clearly: React and TypeScript; accessibility (WCAG) and performance; component testing with Vitest/Playwright. Plus maybe Next.js nice to have.\n\nWord count total under 300.\n\nLet me draft.\n\nParagraph 1: \"I came to software from hospitality. I ran the ordering system at a busy café, taught myself Python to automate the stock count, and that led me to a computer science degree in 2020 and four years as an engineer. I build software that shows its working, so people can trust what it decides. I am a software engineer at Humongous Insurance in Auckland, shipping React and Next.js features in production.\"\n\nThat''s ~4 sentences — allowed \"two or three sentences\" for para 1. Hmm, keep to three. Combine.\n\n\"I came to software from hospitality: I ran the ordering system at a busy café, taught myself Python to automate the stock count, then went back to study computer science. That degree led to four years as an engineer, the last two shipping features in production, and I now work as a Software Engineer at Humongous Insurance in Auckland. My guiding principle is that software should show its working, so people can trust what it decides.\"\n\nGood, three sentences.\n\nParagraph 2: \"I am applying for the Frontend Engineer role at Fourth Coffee. Building the subscription app that 40,000 homes and offices rely on for their coffee is work I would enjoy, and the team''s focus on design systems and speed fits how I like to build.\"\n\nHmm — \"40,000\" is from a given fact, that''s fine. Keep plain.\n\nsWhyGoodFit:\n\nRequirement 1: React and TypeScript. Evidence: rebuilt customer claims portal in Next.js and React, cutting page load 4.1 to 1.3 seconds; typed REST APIs. Sentence: \"The role is built on React and TypeScript, which is the stack I work in daily: at Humongous Insurance I rebuilt the customer claims portal in Next.js and React, and I design typed APIs behind it.\"\n\nRequirement 2: accessibility and performance. Evidence: made booking flow pass WCAG 2.1 AA; page load cut. \"Care for accessibility and speed is the part I take most seriously. I made Margie''s Travel''s booking flow pass WCAG 2.1 AA, and cutting the claims portal page load from 4.1 seconds to 1.3 shows the same care on the performance side.\" Hmm \"4.1 seconds to 1.3\" — numbers from resume, fine.\n\nRequirement 3: component testing with Vitest or Playwright. \"Component testing is something I have added where it was missing: at Margie''s Travel I brought in Vitest and Playwright to a codebase that had none, so regressions were caught before customers saw them.\"\n\nClose sentence: Next.js nice to have... \"Next.js is the framework I reach for by default, and I have used it on both the claims portal and my own projects.\" Maybe that adds.\n\nWord count check. Let''s count roughly.\n\nIntro p1: ~75 words. p2: ~50. Fit section: ~130. Total ~255. Good.\n\nLet me count more carefully.\n\nP1: \"I came to software from hospitality: I ran the ordering system at a busy café, taught myself Python to automate the stock count, then went back to study computer science.\" (29) \"That degree led to four years as an engineer, the last two shipping features in production, and I now work as a Software Engineer at Humongous Insurance in Auckland.\" (30) \"My guiding principle is simple: software should show its working, so people can trust what it decides.\" (17) Total 76.\n\nP2: \"I am applying for the Frontend Engineer role at Fourth Coffee.\" (11) \"The app behind 40,000 homes and offices getting their coffee is the kind of product I want to work on, and owning a design system and making it fast and accessible for everyone is the work I enjoy most.\" (40) Total 51.\n\nFit: \n\"The role is built on React and TypeScript, and that is my daily stack: I rebuilt the Humongous Insurance claims portal in Next.js and React and designed the typed APIs behind it.\" (30)\n\"Accessibility and performance matter to me in the same way; the Margie''s Travel booking flow passed WCAG 2.1 AA, and the claims portal load time came down from 4.1 seconds to 1.3.\" (31)\n\"Component testing is something I have added where it was missing, bringing Vitest and Playwright into a codebase that had none so regressions were caught before customers saw them.\" (28)\n\"Next.js is the framework I reach for first, and I have used it on both the portal and my own projects.\" (21)\n\nTotal fit ~110. Grand total ~237. Good.\n\nCheck banned words: none. No em dashes — I used semicolons and colons, fine. NZ English: \"café\", fine.\n\nActually \"I am applying for the Frontend Engineer role at Fourth Coffee.\" Good.\n\nCareful: \"the app behind 40,000 homes and offices getting their coffee\" — slightly awkward. Rewrite: \"Fourth Coffee delivers subscriptions to 40,000 homes and offices, and building the app those customers use every week is work I would enjoy.\" Hmm \"would enjoy\" fine.\n\nLet me finalize.","reasoningChars":5195,"resume":"Alex_Rivera_CV_Full_Stack.pdf","introParagraphs":2,"words":237,"wordLimit":300,"raw":"{\n  \"aIntroduction\": [\n    \"I came to software from hospitality: I ran the ordering system at a busy café, taught myself Python to automate the stock count, then went back to study computer science. That degree led to four years as an engineer, the last two shipping features in production, and I now work as a Software Engineer at Humongous Insurance in Auckland. My guiding principle is simple: software should show its working, so people can trust what it decides.\",\n    \"I am applying for the Frontend Engineer role at Fourth Coffee. You deliver coffee subscriptions to 40,000 homes and offices, and building the app those customers order from every week, with a design system they can rely on, is the work I enjoy most.\"\n  ],\n  \"sWhyGoodFit\": \"The role is built on React and TypeScript, and that is my daily stack: at Humongous Insurance I rebuilt the customer claims portal in Next.js and React and designed the typed APIs behind it. Accessibility and performance matter to me in the same way, so the Margie''s Travel booking flow passed WCAG 2.1 AA and the claims portal load time came down from 4.1 seconds to 1.3. Component testing is something I have added where it was missing, bringing Vitest and Playwright into a codebase that had none so regressions were caught before customers saw them. Next.js is the framework I reach for first, and I have used it on the portal and on my own projects.\"\n}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('cf1aaea5-240d-4d7d-88db-8a3a0ac3413e', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2043363 seconds'), 26, 0, 1, '[{"tool":"build_pdf","durationMs":26,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I came to software from hospitality: I ran the ordering system at a busy café, taught myself Python to automate the stock count, then went back to study computer science. That degree led to four years as an engineer, the last two shipping features in production, and I now work as a Software Engineer at Humongous Insurance in Auckland. My guiding principle is simple: software should show its workin… (439 chars)","I am applying for the Frontend Engineer role at Fourth Coffee. You deliver coffee subscriptions to 40,000 homes and offices, and building the app those customers order from every week, with a design system they can rely on, is the work I enjoy most."]},{"heading":"Why I Am a Good Fit","paragraphs":["The role is built on React and TypeScript, and that is my daily stack: at Humongous Insurance I rebuilt the customer claims portal in Next.js and React and designed the typed APIs behind it. Accessibility and performance matter to me in the same way, so the Margie''s Travel booking flow passed WCAG 2.1 AA and the claims portal load time came down from 4.1 seconds to 1.3. Component testing is someth… (654 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"Frontend Engineer, Fourth Coffee"}}}]', '{"pages":1,"sizeBytes":2783,"words":277}');
