INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e2c76395-8cbf-4805-b1a5-39a01e136aca', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980980 seconds'), 1835, 504, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an open Software Engineer role with responsibilities, required skills, employer details, and how to apply.","sLooksLike":null,"model":"deepseek-flash","apiMs":1835,"finishReason":"stop","reasoning":"The user wants me to determine if this is a job advertisement. This is clearly a job advertisement - it describes a Software Engineer role at Contoso with responsibilities and requirements.","reasoningChars":189,"inputChars":934,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\": true, \"sReason\": \"It describes an open Software Engineer role with responsibilities, required skills, employer details, and how to apply.\", \"sLooksLike\": null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e2c76395-8cbf-4805-b1a5-39a01e136aca', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980979 seconds'), 2993, 1397, 1, '[]', '{"model":"deepseek-flash","apiMs":2992,"finishReason":"stop","reasoning":"The advert: company Contoso, not agency. Source SEEK. Location Auckland Central. Contract type: Full time listed — \"Full time\" maps to Permanent? The allowed values: Permanent | Fixed-term | Part-time | Contract | Casual | Internship. \"Full time\" isn''t listed; use \"Permanent\" since full time permanent. The advert says \"Full time\" — no mention of fixed-term, so Permanent.\n\nRequirements copy as bullets: \"You have\" bullets. Include nice to have? The requirements section — copy the requirements as \"- \" bullet lines. I''ll include the \"You have\" bullets and nice to have line. Probably include both. I''ll include the four bullets plus nice to have as line.\n\nsCompanyMeta: industry - hospitality/retail software? \"makes rostering and payroll software for hospitality and retail businesses\" — industry: \"SaaS\" or \"Software\". Use \"Software (hospitality & retail SaaS)\"? Keep simple: \"SaaS\". business: one sentence. website_url: null.\n\nsTechStack: TypeScript, React, Node.js, Next.js, PostgreSQL, REST APIs, AWS, GitHub Actions, Playwright.\n\nSourceUrl: null (no URL given).\n\nSummary under 80 words.\n\nRequirements bullet lines copied:\n\n- 2+ years building web applications professionally\n- Strong TypeScript and React\n- Experience with Node.js and relational databases\n- A habit of writing tests\n- Nice to have: AWS, GitHub Actions, Playwright.\n\nReturn JSON only.","reasoningChars":1358,"attempt":1,"promptChars":3236,"responseChars":1147,"raw":"{\"sCompany\":\"Contoso\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Software / SaaS\",\"business\":\"Contoso makes rostering and payroll software for 1,800 New Zealand hospitality and retail businesses.\",\"website_url\":null},\"sJobTitle\":\"Software Engineer (TypeScript)\",\"sJobRequirement\":\"- 2+ years building web applications professionally\\n- Strong TypeScript and React\\n- Experience with Node.js and relational databases\\n- A habit of writing tests\\n- Nice to have: AWS, GitHub Actions, Playwright.\",\"sContractType\":\"Permanent\",\"sLocation\":\"Auckland Central\",\"sJobSummary\":\"Join Contoso''s Scheduling squad to build rostering and payroll features for hospitality and retail customers, including shift planning, leave approvals and labour-cost forecasts. You will work end to end across a Next.js front end and Node.js services, design REST APIs backed by PostgreSQL, write automated tests, maintain the CI pipeline, and pair with product and design. Hybrid working from the Karangahape Road office.\",\"sSource\":\"SEEK\",\"sSourceUrl\":null,\"sTechStack\":[\"TypeScript\",\"React\",\"Node.js\",\"Next.js\",\"PostgreSQL\",\"REST APIs\",\"AWS\",\"GitHub Actions\",\"Playwright\"]}"}');
