INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e2c76395-8cbf-4805-b1a5-39a01e136aca', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980976 seconds'), 94, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e2c76395-8cbf-4805-b1a5-39a01e136aca', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980975 seconds'), 3351, 1824, 1, '[]', '{"model":"deepseek-flash","apiMs":3350,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume. Need judge overlap. Job Software Engineer TypeScript at Contoso scheduling squad, Next.js front end, Node services, REST APIs PostgreSQL, tests, CI, AWS GitHub Actions Playwright nice. Resume 1 AI engineer focuses LLM, but has TypeScript/Python, Node services AWS GitHub Actions, junior full stack React Next PostgreSQL, Vitest Playwright. Resume 2 Full Stack: React Next Node PostgreSQL REST APIs, tests, AWS GitHub Actions Playwright, accessible. It directly matches. So choose resume 2. Need sReason comparative what this resume has others do not, naming advert requirement. Rejected resume 1 one-line reason lacks focus? It has AI/LLM instead of product web scheduling; still has some overlap but not as directly full-stack. Need exact file names.\n\nReturn schema:\n{\n \"sFileName\": \"Alex_Rivera_CV_Full_Stack.pdf\",\n \"sReason\": \"This resume shows end-to-end React/Next.js and Node.js/PostgreSQL product work with typed REST APIs, Vitest/Playwright tests, AWS Lambda and GitHub Actions, directly matching the advert''s core stack and testing/CI requirements; the AI-focused resume foregrounds LLM work rather than the scheduling web product role.\",\n \"aRejected\": [{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"It centers on LLM/AI engineering, so it lacks the advert''s emphasis on React/Next.js full-stack product features, REST/PostgreSQL service design, and conventional web testing.\"}]\n}\n\nNeed ensure one sentence sReason? It says one sentence. We can make one sentence. aRejected one line. Fine.\n\nMaybe mention comparative: what this resume has that others do not. Good.\n\nFinal JSON only.","reasoningChars":1651,"raw":"{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"This resume shows end-to-end React/Next.js and Node.js/PostgreSQL product work with typed REST APIs, Vitest/Playwright tests, AWS Lambda and GitHub Actions, directly matching the advert''s core stack and testing/CI requirements, while the AI-focused resume foregrounds LLM work rather than the scheduling web product role.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"It centers on LLM/AI engineering, so it lacks the advert''s emphasis on React/Next.js full-stack product features, REST/PostgreSQL service design, and conventional web testing.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_Full_Stack.pdf","reason":"This resume shows end-to-end React/Next.js and Node.js/PostgreSQL product work with typed REST APIs, Vitest/Playwright tests, AWS Lambda and GitHub Actions, directly matching the advert''s core stack and testing/CI requirements, while the AI-focused resume foregrounds LLM work rather than the scheduling web product role.","rejected":[{"sFileName":"Alex_Rivera_CV_AI_Engineer.pdf","sReason":"It centers on LLM/AI engineering, so it lacks the advert''s emphasis on React/Next.js full-stack product features, REST/PostgreSQL service design, and conventional web testing."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e2c76395-8cbf-4805-b1a5-39a01e136aca', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980972 seconds'), 6135, 3021, 1, '[]', '{"model":"deepseek-flash","apiMs":6130,"finishReason":"stop","reasoning":"Let me draft.\n\nIntroduction paragraph 1: background from standing highlights: working principle, move into tech, degree, current role. Two or three sentences, own voice.\n\nParagraph 2: why this role, name role and company, mention specific fact about company: Contoso makes rostering and payroll software for 1,800 New Zealand hospitality and retail businesses. And the hospitality background ties nicely.\n\nThen sWhyGoodFit: three requirements most clearly asked: strong TypeScript and React; Node.js and relational databases; habit of writing tests. Maybe close sentence on AWS/GitHub Actions/Playwright nice-to-have. Word count under 300.\n\nLet me write.\n\nPara 1: \"I came to software from hospitality. I ran a busy café''s ordering system, taught myself Python to automate the stock count, and went back to study computer science. I finished my degree in 2020 and I am now a software engineer at Humongous Insurance in Auckland. The principle I work by is simple: make the software show its working, so people can trust what it decides.\"\n\nThat''s 4 sentences; the brief says two or three sentences. Let me trim: \"I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count. That led me to a computer science degree in 2020, and I have spent the last four years building web products, the last two at Humongous Insurance in Auckland. The principle I work by is simple: make the software show its working, so people can trust what it decides.\"\n\nThree sentences. Good.\n\nPara 2: \"I am applying for the Software Engineer (TypeScript) role at Contoso. You build rostering and payroll software for 1,800 New Zealand hospitality and retail businesses, which is the world I came from, so the problems are familiar ones. Building shift planning and labour-cost forecasts that people rely on for their pay is a good use of what I have learned about showing how a system reaches its answer.\"\n\nHmm, avoid \"excited\". Fine.\n\nsWhyGoodFit: \n- TypeScript and React: \"Your role asks for strong TypeScript and React, and I rebuilt the claims portal at Humongous in Next.js and React, which brought page load down from 4.1 to 1.3 seconds.\" Maybe better to mention TypeScript typed APIs.\n- Node.js and relational databases: \"You need Node.js and relational databases, which is what I use to design typed REST APIs and PostgreSQL schemas for the portal and two partner integrations.\"\n- Habit of writing tests: \"Writing tests is a habit for me: I added Vitest and Playwright to a booking codebase that had none, and the tests caught release regressions before customers saw them.\"\n- Close: AWS, GitHub Actions, Playwright already mentioned Playwright. Maybe close: \"I also moved four Node.js services to AWS Lambda with GitHub Actions deployments, which covers the nice-to-have list.\"\n\nCount words. Let me count roughly.\n\nPara1: I(1) came2 to3 software4 from5 hospitality,6 where7 I8 ran9 a10 busy11 café''s12 ordering13 system14 and15 taught16 myself17 Python18 to19 automate20 the21 stock22 count.23 That24 led25 me26 to27 a28 computer29 science30 degree31 in32 2020,33 and34 I35 have36 spent37 the38 last39 four40 years41 building42 web43 products,44 the45 last46 two47 at48 Humongous49 Insurance50 in51 Auckland.52 The53 principle54 I55 work56 by57 is58 simple:59 make60 the61 software62 show63 its64 working,65 so66 people67 can68 trust69 what70 it71 decides.72\n\nPara2: I73 am74 applying75 for76 the77 Software78 Engineer79 (TypeScript)80 role81 at82 Contoso.83 You84 build85 rostering86 and87 payroll88 software89 for90 1,80091 New92 Zealand93 hospitality94 and95 retail96 businesses,97 which98 is99 the100 world101 I102 came103 from,104 so105 the106 problems107 are108 familiar109 ones.110 Building111 shift112 planning113 and114 labour-cost115 forecasts116 that117 people118 rely119 on120 for121 their122 pay123 is124 a125 good126 use127 of128 what129 I130 have131 learned132 about133 showing134 how135 a136 system137 reaches138 its139 answer.140\n\nGood fit: Your141 role142 asks143 for144 strong145 TypeScript146 and147 React,148 and149 I150 rebuilt151 the152 claims153 portal154 at155 Humongous156 in157 Next.js158 and159 React,160 which161 brought162 page163 load164 down165 from166 4.1167 to168 1.3169 seconds.170 You171 need172 Node.js173 and174 relational175 databases,176 which177 is178 what179 I180 use181 to182 design183 typed184 REST185 APIs186 and187 PostgreSQL188 schemas189 for190 the191 portal192 and193 two194 partner195 integrations.196 Writing197 tests198 is199 a200 habit201 of202 mine:203 I204 added205 Vitest206 and207 Playwright208 to209 a210 booking211 codebase212 that213 had214 none,215 and216 they217 caught218 release219 regressions220 before221 customers222 saw223 them.224 I225 also226 moved227 four228 Node.js229 services230 to231 AWS232 Lambda233 with234 GitHub235 Actions236 deployments,237 which238 covers239 the240 nice-to-have241 list.242\n\n242 words. Under 300. Good.\n\nCheck banned words: none. No em dashes. NZ English: \"labour-cost\", \"café''s\". \"1,800\" fine.\n\nSchema: JSON only with keys aIntroduction (array of two paragraphs) and sWhyGoodFit (string).","reasoningChars":5140,"resume":"Alex_Rivera_CV_Full_Stack.pdf","introParagraphs":2,"words":242,"wordLimit":300,"raw":"{\"aIntroduction\":[\"I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count. That led me to a computer science degree in 2020, and I have spent the last four years building web products, the last two at Humongous Insurance in Auckland. The principle I work by is simple: make the software show its working, so people can trust what it decides.\",\"I am applying for the Software Engineer (TypeScript) role at Contoso. You build rostering and payroll software for 1,800 New Zealand hospitality and retail businesses, which is the world I came from, so the problems are familiar ones. Building shift planning and labour-cost forecasts that people rely on for their pay is a good use of what I have learned about showing how a system reaches its answer.\"],\"sWhyGoodFit\":\"Your role asks for strong TypeScript and React, and I rebuilt the claims portal at Humongous in Next.js and React, which brought page load down from 4.1 to 1.3 seconds. You need Node.js and relational databases, which is what I use to design typed REST APIs and PostgreSQL schemas for the portal and two partner integrations. Writing tests is a habit of mine: I added Vitest and Playwright to a booking codebase that had none, and they caught release regressions before customers saw them. I also moved four Node.js services to AWS Lambda with GitHub Actions deployments, which covers the nice-to-have list.\"}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e2c76395-8cbf-4805-b1a5-39a01e136aca', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4980966 seconds'), 210, 0, 1, '[{"tool":"build_pdf","durationMs":207,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count. That led me to a computer science degree in 2020, and I have spent the last four years building web products, the last two at Humongous Insurance in Auckland. The principle I work by is simple: make the software show its working, so people can trust what it decides.","I am applying for the Software Engineer (TypeScript) role at Contoso. You build rostering and payroll software for 1,800 New Zealand hospitality and retail businesses, which is the world I came from, so the problems are familiar ones. Building shift planning and labour-cost forecasts that people rely on for their pay is a good use of what I have learned about showing how a system reaches its answe… (402 chars)"]},{"heading":"Why I Am a Good Fit","paragraphs":["Your role asks for strong TypeScript and React, and I rebuilt the claims portal at Humongous in Next.js and React, which brought page load down from 4.1 to 1.3 seconds. You need Node.js and relational databases, which is what I use to design typed REST APIs and PostgreSQL schemas for the portal and two partner integrations. Writing tests is a habit of mine: I added Vitest and Playwright to a booki… (607 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"Software Engineer (TypeScript), Contoso"}}}]', '{"pages":1,"sizeBytes":2843,"words":282}');
