INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e318a497-9f06-4d81-919b-481f0902b565', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-142580 seconds'), 1036, 464, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an open Backend Engineer role with responsibilities, requirements, location, and benefits.","sLooksLike":null,"model":"deepseek-flash","apiMs":1036,"finishReason":"stop","reasoning":"We need answer JSON only. Need decide if job ad. Clearly yes. Need schema. sLooksLike null when job ad. Reason short. Ensure valid JSON.","reasoningChars":136,"inputChars":719,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\": true, \"sReason\": \"It describes an open Backend Engineer role with responsibilities, requirements, location, and benefits.\", \"sLooksLike\": null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('e318a497-9f06-4d81-919b-481f0902b565', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-142579 seconds'), 9254, 2952, 1, '[]', '{"model":"deepseek-flash","apiMs":9254,"finishReason":"stop","reasoning":"We need answer JSON only. Need extract. Let''s parse.\n\nAdvert:\nBackend Engineer\nAlpine Ski House · Queenstown or remote (NZ) · Full time\n\nAlpine Ski House runs lift-pass, lesson and rental bookings for four ski areas in Southern Alps.\nWinter traffic spiky, reliability matters.\n\nWhat you will do...\nWhat you need:\n- 3+ years...\n- TypeScript and Node.js\n- PostgreSQL and caching\n- Experience with serverless or edge platforms\n- Calm under pressure\n\nSeason pass... Relocation support.\n\nsCompany: Alpine Ski House. bAgency false (direct employer). sCompanyMeta industry? Travel/Tourism? Advert says runs lift-pass, lesson and rental bookings for ski areas. Industry could be Ski resort software / Travel & Tourism / Hospitality? We should use info present. It doesn''t state industry explicitly. Could be \"Ski resort booking software\" maybe infer? Rules never infer/invent. The advert describes what company does; industry maybe null or \"Ski and travel bookings\"? It asks string | null e.g. Agritech, Banking, Healthcare. Since not explicitly \"industry\" maybe null. But business can be one sentence. website_url null (not given). sJobTitle: Backend Engineer. sJobRequirement: copy requirements as \"- \" bullet lines. Keep wording. Requirements section: \"- 3+ years of backend development\\n- TypeScript and Node.js\\n- PostgreSQL and caching\\n- Experience with serverless or edge platforms\\n- Calm under pressure\". Could also include \"What you will do\" not requirements. We''ll include only need. sContractType: Full time stated. Options include Permanent, Fixed-term, Part-time, Contract, Casual, Internship. \"Full time\" isn''t in enum except Part-time? Hmm instructions: sContractType: \"Permanent | Fixed-term | Part-time | Contract | Casual | Internship - use Permanent when the advert does not say\". Advert says \"Full time\" but schema enum doesn''t include Full-time. Need decide. The instruction says use Permanent when advert does not state. It states Full time, which implies Permanent? But enum does not include Full-time. Maybe sContractType should be \"Permanent\" because full time is not contract type? Hmm. They said sContractType: when the advert does not state the employment type, use \"Permanent\". Here employment type \"Full time\" but not in allowed values. Perhaps \"Permanent\" is closest? But \"Full time\" could be permanent full-time. The required shape says \"Permanent | Fixed-term | Part-time | Contract | Casual | Internship - use Permanent when the advert does not say\". Since Full time is not listed, but advert does say full time. Maybe we should return \"Permanent\"? Or maybe invalid if \"Full time\". Strict JSON and schema? Need adhere. In similar tasks, they want one of enum. If ad says Full time, maybe map to Permanent? Hmm.\n\nsLocation: \"Queenstown or remote (NZ)\" as specific. Could be \"Queenstown or remote (NZ)\" or \"Queenstown, remote (NZ)\". Use exactly? \"Queenstown or remote (NZ) · Full time\" appears. sLocation as specific as advert allows: \"Queenstown or remote (NZ)\". Good.\n\nsJobSummary under 80 words: Backend Engineer at Alpine Ski House building booking and payment services in TypeScript on Node.js, scaling APIs for winter traffic spikes, running on Cloudflare Workers and AWS, improving observability. Requires 3+ years backend, TypeScript/Node.js, PostgreSQL, caching, serverless/edge. Queenstown or remote NZ. Full time. Under 80. Maybe no selling. Good.\n\nsSource: The advert text doesn''t include source. It might be from some job board? No URL. sSource: \"SEEK | LinkedIn | Company Website | Trade Me Jobs | Other\". Since no source indicated. The source could be \"Company Website\"? But no info. We need null? But schema says sSource string. Maybe \"Other\" because unknown. But rules: use only info present. If not stated, null? But schema does not allow null? It says sSource: \"SEEK | LinkedIn | Company Website | Trade Me Jobs | Other\". We don''t know. Could set \"Other\". The ad might be from company website? No evidence. We can set \"Other\". sSourceUrl null.\n\nsTechStack: named technologies: TypeScript, Node.js, Cloudflare Workers, AWS, PostgreSQL. Maybe \"caching\" not named tech. \"serverless or edge platforms\" not specific tech. \"logs, traces and alerts\" not tech. So list.\n\nIndustry: could be \"Ski resort bookings\" maybe not exactly industry. The instruction says industry e.g. Agritech, Banking, Healthcare. The advert says \"runs lift-pass, lesson and rental bookings for four ski areas in the Southern Alps.\" Industry maybe \"Travel & Tourism\" or \"Ski resort software\". But is that inferred? It is directly described. \"Ski\" or \"Travel\" okay? Maybe null because not explicit industry label. Business: one sentence: \"Alpine Ski House runs lift-pass, lesson and rental bookings for four ski areas in the Southern Alps.\" Good. website_url null.\n\nNeed ensure bAgency false. For agency advert, sCompany agency name. Here direct.\n\nPotential issue: sJobRequirement copy requirements as \"- \" bullet lines. The advert''s \"What you need\" section includes those bullets. We can copy exactly including \"Calm under pressure\". Good.\n\nsContractType: Full time. Allowed list lacks Full time. Could use \"Permanent\" because full-time usually permanent and instruction says use Permanent when advert does not say. But here says Full time. Hmm. The schema explicitly: \"Permanent | Fixed-term | Part-time | Contract | Casual | Internship - use Permanent when the advert does not say\". If advert says Full time, it does state something, but not among allowed. Maybe return \"Permanent\" to satisfy enum. Alternatively \"Full time\" violates schema. We want strict schema. The user likely expects one of enum. In many such extraction tasks, if ad says full-time, they''d map to \"Permanent\" because full-time is not contract type. But instruction says sContractType: when advert does not state employment type, use \"Permanent\". It states \"Full time\" employment type? Actually \"Full time\" is employment type. Hmm. But no allowed full-time. Could use \"Permanent\" as default. I''ll use \"Permanent\". I…","reasoningChars":8159,"attempt":1,"promptChars":3021,"responseChars":992,"raw":"{\"sCompany\":\"Alpine Ski House\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":null,\"business\":\"Alpine Ski House runs lift-pass, lesson and rental bookings for four ski areas in the Southern Alps.\",\"website_url\":null},\"sJobTitle\":\"Backend Engineer\",\"sJobRequirement\":\"- 3+ years of backend development\\n- TypeScript and Node.js\\n- PostgreSQL and caching\\n- Experience with serverless or edge platforms\\n- Calm under pressure\",\"sContractType\":\"Permanent\",\"sLocation\":\"Queenstown or remote (NZ)\",\"sJobSummary\":\"Backend Engineer at Alpine Ski House building booking and payment services in TypeScript on Node.js. Scale APIs for 50x winter traffic, run services on Cloudflare Workers and AWS, and improve observability. Requires 3+ years backend development plus TypeScript, Node.js, PostgreSQL, caching, and serverless or edge platform experience. Queenstown or remote in New Zealand.\",\"sSource\":\"Other\",\"sSourceUrl\":null,\"sTechStack\":[\"TypeScript\",\"Node.js\",\"Cloudflare Workers\",\"AWS\",\"PostgreSQL\"]}"}');
