INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('eea14fb5-829e-490c-89b5-7dc981b25c77', 1, 'main', 'identify', 'Is this a job advertisement?', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857780 seconds'), 1205, 504, 1, '[]', '{"bIsJobPost":true,"sReason":"It describes an open Full Stack Developer role with responsibilities, requirements, salary, and application details.","sLooksLike":null,"model":"deepseek-flash","apiMs":1204,"finishReason":"stop","reasoning":"We need answer JSON only. Need determine if job advertisement. Text clearly job ad: title, company, location, responsibilities, requirements, salary. So bIsJobPost true. sReason short. sLooksLike null because it is job ad. Need adhere schema.","reasoningChars":242,"inputChars":843,"instructions":"You decide whether a block of text is a job advertisement.\n\nA job advertisement describes a role someone can apply for: the work, what is\nrequired, who the employer is, or how to apply. Pasted adverts often carry\nwebsite clutter around them (\"Apply now\", \"Save job\", cookie notices, \"Posted 3\ndays ago\") — ignore the clutter and judge the substance.\n\nThese are NOT job advertisements: a company profile, a news article, a CV or\nresume, an email, a product page, notes, or a list of unrelated text.\n\nReturn JSON only:\n{\n  \"bIsJobPost\": true or false,\n  \"sReason\": \"one short sentence saying why\",\n  \"sLooksLike\": \"what the text actually is, when it is not a job advertisement, otherwise null\"\n}","raw":"{\"bIsJobPost\":true,\"sReason\":\"It describes an open Full Stack Developer role with responsibilities, requirements, salary, and application details.\",\"sLooksLike\":null}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('eea14fb5-829e-490c-89b5-7dc981b25c77', 2, 'extractor', 'extract', 'Read the advert and return structured JSON', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857779 seconds'), 9598, 3123, 1, '[]', '{"model":"deepseek-flash","apiMs":9598,"finishReason":"stop","reasoning":"We need answer JSON only. Need extract. Let''s parse carefully.\n\nAdvert:\nFull Stack Developer\nTailwind Traders · Auckland (hybrid) · Full time\nFound on LinkedIn · Easy apply\n\nTailwind Traders is an online hardware retailer shipping to every corner of Aotearoa from our Penrose warehouse. Our in-house team of 12 builds the storefront, the warehouse app and everything in between.\n\nResponsibilities...\nRequirements...\n\nPermanent role, salary $105k to $125k, staff discount on everything we sell.\n\nNeed sCompany: Tailwind Traders. bAgency false (not agency). sCompanyMeta industry? online hardware retailer. Could say \"Hardware Retail\" or \"Retail\". business: one sentence. website_url? Advert doesn''t show company website. null. Job title Full Stack Developer. sJobRequirement copy requirements as \"- \" bullet lines. Include bonus? Requirements section. \"Requirements\" four bullets. Bonus points for Shopify, Stripe or GraphQL experience. Maybe include as requirement? The field says requirements copied from advert. Could include all under Requirements and Bonus points? Probably include requirements bullets as they are. \"Bonus points for...\" is not a requirement but relevant. We can include maybe as bullet \"- Bonus points for Shopify, Stripe or GraphQL experience.\" But instruction: sJobRequirement: copy the requirements as \"- \" bullet lines. Keep advert''s wording. The advert has \"Requirements\" heading. So include those four. Could also include bonus? Hmm. The field likely expects requirements. Bonus points is not requirement. But maybe it''s useful. However strict extraction. We can include only requirements bullets. But if we include bonus, it''s not under Requirements. It''s a bonus. The schema says \"the requirements as ''- '' bullet lines, copied from the advert\". It doesn''t say include bonuses. I''d include Requirements section, maybe also \"Bonus points...\"? Let''s think. Many job extraction tasks include requirements and nice-to-haves in same field? The field name singular \"sJobRequirement\" likely all requirements including preferred. But the advert separates \"Requirements\" and \"Bonus points for...\". To be safe, include both as bullet lines, with exact wording: \n- 3+ years of full-stack JavaScript or TypeScript\n- Next.js or similar React framework in production\n- PostgreSQL or MySQL\n- Experience integrating third-party APIs\n- Bonus points for Shopify, Stripe or GraphQL experience\nThat is copied. It says \"Bonus points for Shopify, Stripe or GraphQL experience.\" If we add \"- \" bullet. Good.\n\nsContractType: Permanent role stated. So \"Permanent\".\nsLocation: Auckland (hybrid) from header. Maybe \"Auckland (hybrid)\" as specific. Also Penrose warehouse. The ad says Auckland (hybrid). So sLocation: \"Auckland (hybrid)\".\nsJobSummary: under 80 words, plain description, no selling. Mention in-house team builds storefront, warehouse app; role builds storefront/checkout with Next.js/React, maintains APIs Node.js, integrations, performance/accessibility. Under 80. \nsSource: LinkedIn (Found on LinkedIn). \nsSourceUrl: advert URL if appears in text. It doesn''t. null.\nsTechStack: named technologies: Next.js, React, Node.js, JavaScript, TypeScript, PostgreSQL, MySQL, Shopify, Stripe, GraphQL. Also maybe \"APIs\"? Not named tech. Third-party APIs not named. Include named. Maybe \"Tailwind\"? Wait company \"Tailwind Traders\" could be mistaken for Tailwind CSS? The ad says Tailwind Traders as company. No Tailwind CSS mentioned. So don''t include Tailwind. Include all named technologies. \"JavaScript or TypeScript\" so both. \"Next.js\", \"React\", \"Node.js\", \"PostgreSQL\", \"MySQL\", \"Shopify\", \"Stripe\", \"GraphQL\". Good.\nsCompanyMeta: \nindustry: \"Online hardware retail\" or \"Hardware Retail\". The schema e.g. Agritech, Banking, Healthcare. So \"Retail\" maybe. Business: \"Tailwind Traders is an online hardware retailer shipping to every corner of Aotearoa from its Penrose warehouse.\" website_url: null (not in text). It says company''s own site, never job board. Advert does not show it. null.\nsCompany: \"Tailwind Traders\"\nbAgency: false.\nNeed valid JSON. Boolean false not string? Schema says \"boolean\" but example string? It says bAgency: \"boolean - true...\" In required shape, value is string? Actually shape shows \"bAgency\": \"boolean - ...\" but in JSON it should be boolean. We''ll output false.\n\nEnsure no markdown fences. JSON only.\n\nLet''s craft summary under 80 words. Count. \n\"Tailwind Traders is an online hardware retailer with a 12-person in-house team. The Full Stack Developer builds storefront and checkout features in Next.js and React, maintains order and inventory APIs in Node.js, integrates courier and payment providers, and improves site performance and accessibility. Permanent role based in Auckland with hybrid work.\" \nWords: Tailwind(1) Traders(2) is3 an4 online5 hardware6 retailer7 with8 a9 12-person10 in-house11 team12. The13 Full14 Stack15 Developer16 builds17 storefront18 and19 checkout20 features21 in22 Next.js23 and24 React25, maintains26 order27 and28 inventory29 APIs30 in31 Node.js32, integrates33 courier34 and35 payment36 providers37, and38 improves39 site40 performance41 and42 accessibility43. Permanent44 role45 based46 in47 Auckland48 with49 hybrid50 work51. Good.\n\nsJobRequirement string with newline escapes. Need JSON. Could be:\n\"- 3+ years of full-stack JavaScript or TypeScript\\n- Next.js or similar React framework in production\\n- PostgreSQL or MySQL\\n- Experience integrating third-party APIs\\n- Bonus points for Shopify, Stripe or GraphQL experience\"\n\nShould we include bonus? Let''s decide. I think yes, as it is part of requirements / desirables. If strict, maybe only four bullets. The instruction: \"sJobRequirement: copy the requirements as ''- '' bullet lines. Keep the advert''s wording.\" The advert has \"Requirements\" heading. Bonus points is separate. If I include bonus, it''s still copied. Usually in extraction, bonus points are part of job requirements. But maybe sJobRequirement should include all required skills. The bonus is not …","reasoningChars":8981,"attempt":1,"promptChars":3145,"responseChars":1109,"raw":"{\"sCompany\":\"Tailwind Traders\",\"bAgency\":false,\"sCompanyMeta\":{\"industry\":\"Hardware retail\",\"business\":\"Tailwind Traders is an online hardware retailer shipping to every corner of Aotearoa from its Penrose warehouse.\",\"website_url\":null},\"sJobTitle\":\"Full Stack Developer\",\"sJobRequirement\":\"- 3+ years of full-stack JavaScript or TypeScript\\n- Next.js or similar React framework in production\\n- PostgreSQL or MySQL\\n- Experience integrating third-party APIs\\n- Bonus points for Shopify, Stripe or GraphQL experience\",\"sContractType\":\"Permanent\",\"sLocation\":\"Auckland (hybrid)\",\"sJobSummary\":\"Tailwind Traders is an online hardware retailer with a 12-person in-house team. The Full Stack Developer builds storefront and checkout features in Next.js and React, maintains order and inventory APIs in Node.js, integrates courier and payment providers, and improves site performance and accessibility. Permanent role based in Auckland with hybrid work.\",\"sSource\":\"LinkedIn\",\"sSourceUrl\":null,\"sTechStack\":[\"Next.js\",\"React\",\"Node.js\",\"JavaScript\",\"TypeScript\",\"PostgreSQL\",\"MySQL\",\"Shopify\",\"Stripe\",\"GraphQL\"]}"}');
