INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('eea14fb5-829e-490c-89b5-7dc981b25c77', 8, 'cover-letter', 'load-resumes', 'Read the resumes in storage', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857770 seconds'), 27, 0, 1, '[{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_AI_Engineer.pdf: 1 page(s), 1821 chars","detail":{"key":"resume/Alex_Rivera_CV_AI_Engineer.pdf","note":"AI engineering and LLM applications"}},{"tool":"pdf_text","durationMs":0,"ok":true,"summary":"Alex_Rivera_CV_Full_Stack.pdf: 1 page(s), 1586 chars","detail":{"key":"resume/Alex_Rivera_CV_Full_Stack.pdf","note":"full-stack and frontend web development"}}]', '{"found":2,"files":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"skipped":[]}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('eea14fb5-829e-490c-89b5-7dc981b25c77', 9, 'cover-letter', 'choose-resume', 'Pick the resume that fits this role', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857770 seconds'), 3603, 1821, 1, '[]', '{"model":"deepseek-flash","apiMs":3601,"finishReason":"stop","reasoning":"We need answer JSON only. Need pick best resume. Two resumes same person tailored. Job full stack Next.js React Node PostgreSQL third-party APIs, bonus Shopify Stripe GraphQL. Resume 2 is full-stack, matches Next.js React Node PostgreSQL, accessibility, APIs, etc. Resume 1 AI engineer, has TypeScript/Node, some full-stack junior with React Next.js PostgreSQL, but aimed AI/LLM, lacks current full-stack production, frontend performance/accessibility maybe. Need comparative reason and rejected one line. Must include exact filename. Use given file names: Alex_Rivera_CV_AI_Engineer.pdf and Alex_Rivera_CV_Full_Stack.pdf. Need sReason one sentence: what this resume shows others do not against advert. Rejected list with one line each. Only one rejected? There are two resumes, choose resume2, reject resume1. Ensure JSON.\n\nNeed be careful: \"Full Stack Developer\" role, resume2 has production Next.js/React, Node/PostgreSQL, third-party partner integrations, WCAG, performance. Resume1 has AI, but has some full stack experience, but not as aligned. Reason comparative: \"Unlike the AI-focused resume, this resume shows current production Next.js/React storefront/portal work with Node.js and PostgreSQL APIs, performance and WCAG improvements, and third-party integrations, directly matching the advert''s main tasks.\" Rejected: AI resume emphasizes LLM/AI engineering, so lacks enough evidence of production full-stack Next.js/React, courier/payment integrations, e-commerce/checkout focus. Need maybe mention third-party APIs? It has partner integrations? Resume2 has partner integrations. Resume1 has no Stripe/Shopify/GraphQL either. Bonus not required. Resume2 also no Shopify/Stripe/GraphQL? It mentions partner integrations, not Shopify Stripe GraphQL. But better.\n\nReturn JSON only.","reasoningChars":1790,"raw":"{\"sFileName\":\"Alex_Rivera_CV_Full_Stack.pdf\",\"sReason\":\"Unlike the AI-focused resume, this resume shows production Next.js/React web work, Node.js/PostgreSQL APIs, third-party partner integrations, and explicit performance and WCAG accessibility improvements, directly matching Tailwind Traders'' storefront, checkout, API and site quality needs.\",\"aRejected\":[{\"sFileName\":\"Alex_Rivera_CV_AI_Engineer.pdf\",\"sReason\":\"It is aimed at AI and LLM engineering, so it lacks comparable evidence of current production full-stack Next.js/React e-commerce or checkout work and courier/payment API integration.\"}]}","candidates":["Alex_Rivera_CV_AI_Engineer.pdf","Alex_Rivera_CV_Full_Stack.pdf"],"chose":"Alex_Rivera_CV_Full_Stack.pdf","reason":"Unlike the AI-focused resume, this resume shows production Next.js/React web work, Node.js/PostgreSQL APIs, third-party partner integrations, and explicit performance and WCAG accessibility improvements, directly matching Tailwind Traders'' storefront, checkout, API and site quality needs.","rejected":[{"sFileName":"Alex_Rivera_CV_AI_Engineer.pdf","sReason":"It is aimed at AI and LLM engineering, so it lacks comparable evidence of current production full-stack Next.js/React e-commerce or checkout work and courier/payment API integration."}],"error":null}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('eea14fb5-829e-490c-89b5-7dc981b25c77', 10, 'cover-letter', 'write-letter', 'Write the introduction and the fit section', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857766 seconds'), 9830, 3720, 1, '[]', '{"model":"deepseek-flash","apiMs":9830,"finishReason":"stop","reasoning":"Let me write JSON with aIntroduction (two paragraphs) and sWhyGoodFit (3-4 sentences prose). Total 300 words max.\n\nIntroduction paragraph 1: background from standing highlights: working principle, move into tech, degree, current role. Two or three sentences, keep their voice.\n\nPara 2: why this role. Name role and company. Mention specific company fact only if given: online hardware retailer shipping to every corner of Aotearoa from Penrose warehouse, 12-person in-house team.\n\nsWhyGoodFit: three requirements from advert: 3+ years full-stack JavaScript/TypeScript; Next.js or similar React framework in production; PostgreSQL or MySQL; third-party API integration. Pick three most clearly asked: full-stack JS/TS experience, Next.js in production, PostgreSQL, third-party API integration. Pick three: 3+ years full-stack JS/TS (four years), Next.js in production (claims portal), PostgreSQL (typed REST APIs), third party APIs (courier/payment? resume says partner integrations). Let''s do three sentences plus optional closing.\n\nWord count careful. Let''s draft.\n\nParagraph 1:\n\"I came to software from hospitality. I ran a busy café''s ordering system, taught myself Python to automate the stock count, then went back to study computer science. I finished my degree in 2020 and have spent four years as a software engineer, the last two building language model features that run in production. I now work at Humongous Insurance in Auckland. My rule is simple: make the software show its working, so people can trust what it decides.\"\n\nThat''s ~85 words. Maybe trim.\n\nParagraph 2:\n\"I am applying for the Full Stack Developer role at Tailwind Traders. What draws me is the scale of a storefront that ships to every corner of Aotearoa, and the fact that a 12-person team builds all of it in house. That is the kind of place where one developer''s work shows up on the site quickly, and where checkout and order code has to be right the first time.\"\n\n~72 words.\n\nsWhyGoodFit: 3-4 sentences.\n\"You ask for three or more years of full-stack JavaScript, and I have four, split between React and Next.js on the front end and Node.js with PostgreSQL behind them. The role needs Next.js in production, which is what I do now: I rebuilt the claims portal at Humongous Insurance in Next.js and React and cut page load from 4.1 seconds to 1.3. You also list PostgreSQL, and I have designed typed REST APIs on it for the portal and two partner integrations, so working with outside providers is familiar ground.\"\n\nMaybe add closing sentence about accessibility/performance since advert mentions improving site performance and accessibility. Maybe a fourth sentence instead of the API one? Advert asks: 3+ yrs, Next.js, PostgreSQL/MySQL, third-party APIs. Three most clearly asked: probably 3+ years full stack, Next.js production, third-party API integration or PostgreSQL. I''ll do three sentences and a closing on performance/accessibility which adds something.\n\nLet''s restructure:\n\n1. \"You ask for three or more years of full-stack JavaScript, and I have four, mostly in React and Next.js with Node.js behind them.\" — good.\n2. Next.js production: rebuilt claims portal, 4.1 to 1.3 seconds.\n3. Third-party APIs... PostgreSQL: \"The role also brings courier and payment providers into the checkout, and I have integrated outside systems before: typed Node.js and PostgreSQL REST APIs for two partner integrations.\" Hmm, resume says \"Designed typed REST APIs in Node.js and PostgreSQL for the portal and two partner integrations.\" Careful: not claiming courier/payment specifically. Fine.\n4. Closing: \"The advert also mentions performance and accessibility, which is work I have done: WCAG 2.1 AA on a booking flow and a page load cut from 4.1 to 1.3 seconds.\" But 4.1 to 1.3 already used. Use WCAG booking flow at Margie''s Travel.\n\nWord count total: need ≤300. Let me count.\n\nIntro para1 (~80), para2 (~70) = 150. Fit section ~110. Total ~260. Good.\n\nLet me tighten and count precisely.\n\nPara 1:\n\"I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count. That led me back to study computer science, and I finished my degree in 2020. Four years on, I am a software engineer at Humongous Insurance in Auckland, and my rule has not changed: make the software show its working, so people can trust what it decides.\"\n\nCount: I(1) came2 to3 software4 from5 hospitality6 where7 I8 ran9 a10 busy11 café''s12 ordering13 system14 and15 taught16 myself17 Python18 to19 automate20 the21 stock22 count23. That24 led25 me26 back27 to28 study29 computer30 science31 and32 I33 finished34 my35 degree36 in37 2020 38. Four39 years40 on41 I42 am43 a44 software45 engineer46 at47 Humongous48 Insurance49 in50 Auckland51 and52 my53 rule54 has55 not56 changed57 make58 the59 software60 show61 its62 working63 so64 people65 can66 trust67 what68 it69 decides70. ~70 words.\n\nPara 2:\n\"The Full Stack Developer role at Tailwind Traders is the one I want. Tailwind ships to every corner of Aotearoa from a Penrose warehouse with a 12-person team in house, which means the person writing checkout code can see it live on the site the same week. That is the work I want to do.\"\n\nCount: ~54 words. Good.\n\nFit section:\n\"You ask for three or more years of full-stack JavaScript, and I have four, most of them in React and Next.js with Node.js and PostgreSQL behind them. The role calls for Next.js in production, which is what I do now: I rebuilt the claims portal at Humongous Insurance in Next.js and React and cut page load from 4.1 seconds to 1.3. Courier and payment providers are new to me, but connecting outside systems is not, since I have designed typed Node.js and PostgreSQL APIs for the portal and two partner integrations. On the side the advert mentions performance and accessibility, I have taken a booking flow to WCAG 2.1 AA and added the Vitest and Playwright tests that catch regressions before customers do.\"\n\nHmm \"On the side the advert mentions\" is gar…","reasoningChars":7944,"resume":"Alex_Rivera_CV_Full_Stack.pdf","introParagraphs":2,"words":241,"wordLimit":300,"raw":"{\n  \"aIntroduction\": [\n    \"I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count. That led me back to study computer science, and I finished my degree in 2020. Four years on, I am a software engineer at Humongous Insurance in Auckland, and my rule has not changed: make the software show its working, so people can trust what it decides.\",\n    \"The Full Stack Developer role at Tailwind Traders is the one I want. Tailwind ships to every corner of Aotearoa from a Penrose warehouse with a 12-person team in house, which means the person writing checkout code can see it live on the site the same week. That is the work I want to do.\"\n  ],\n  \"sWhyGoodFit\": \"You ask for three or more years of full-stack JavaScript, and I have four, most of them in React and Next.js with Node.js and PostgreSQL behind them. The role calls for Next.js in production, which is what I do now: I rebuilt the claims portal at Humongous Insurance in Next.js and React and cut page load from 4.1 seconds to 1.3. Courier and payment providers would be new to me, but connecting outside systems is not, since I have designed typed Node.js and PostgreSQL APIs for the portal and two partner integrations. Accessibility also appears in the advert, and at Margie''s Travel I took the booking flow through an accessibility audit and fixed what it found.\"\n}"}');
INSERT INTO AgentRunStep (sRunUUID, iSeq, sAgent, sName, sLabel, sStatus, dtDateTime, iDurationMs, iTokens, iAttempt, sTools, sDetail) VALUES ('eea14fb5-829e-490c-89b5-7dc981b25c77', 11, 'cover-letter', 'build-pdf', 'Render the letter as a one-page PDF', 'ok', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3857756 seconds'), 6, 0, 1, '[{"tool":"build_pdf","durationMs":5,"ok":true,"summary":"1 page(s), 3KB","detail":{"input":{"letter":{"name":"Alex Rivera","contactLines":["Auckland","021 555 0142  |  alex.rivera@inspectcopilot.com"],"salutation":"Dear Hiring Team","sections":[{"heading":"Introduction","paragraphs":["I came to software from hospitality, where I ran a busy café''s ordering system and taught myself Python to automate the stock count. That led me back to study computer science, and I finished my degree in 2020. Four years on, I am a software engineer at Humongous Insurance in Auckland, and my rule has not changed: make the software show its working, so people can trust what it decides.","The Full Stack Developer role at Tailwind Traders is the one I want. Tailwind ships to every corner of Aotearoa from a Penrose warehouse with a 12-person team in house, which means the person writing checkout code can see it live on the site the same week. That is the work I want to do."]},{"heading":"Why I Am a Good Fit","paragraphs":["You ask for three or more years of full-stack JavaScript, and I have four, most of them in React and Next.js with Node.js and PostgreSQL behind them. The role calls for Next.js in production, which is what I do now: I rebuilt the claims portal at Humongous Insurance in Next.js and React and cut page load from 4.1 seconds to 1.3. Courier and payment providers would be new to me, but connecting outs… (665 chars)"]},{"heading":"Additional Information","paragraphs":["I currently hold a valid open work visa valid until June 2028. I am available to start work after serving my 2-week notice period."]}],"signOff":"Kind regards"},"title":"Full Stack Developer, Tailwind Traders"}}}]', '{"pages":1,"sizeBytes":2744,"words":281}');
